import type { AudioEngine, BusName } from "../audio/AudioEngine.ts";
import type { AnnounceMode } from "../ui/Prefs.ts";
import type { RadioLog } from "../ui/RadioLog.ts";
import { clipLookupCandidates } from "./deliveryTone.ts";
import type { SpeechVoiceBackend } from "./SpeechVoiceBackend.ts";
import { estimateSpokenSeconds, type Phrase, type SpeakHandle, type VoiceBackend } from "./VoiceBackend.ts";

/**
 * SampledVoiceBackend — play directed booth WAVs on the announcer/color buses.
 *
 * Missing clips log only (no OS Web Speech) so the cast identity stays intact.
 * Clips sit on the Web Audio graph (AM filter applies when enabled).
 */

export interface BoothClipEntry {
  /** Path relative to the booth base URL, e.g. `call.hr.0__hot.wav`. */
  file: string;
  durationSec?: number;
}

export interface BoothManifest {
  version: number;
  voices?: { announcer?: string; color?: string };
  clips: Record<string, BoothClipEntry>;
}

export interface SampledVoiceBackendOptions {
  engine: AudioEngine;
  log: RadioLog;
  fallback: SpeechVoiceBackend;
  getAnnounceMode: () => AnnounceMode;
  /** Defaults to Vite public path resolved beside the bundle (`../sounds/booth/`). */
  baseUrl?: URL;
  /** Optional preloaded manifest (tests). */
  manifest?: BoothManifest;
}

export class SampledVoiceBackend implements VoiceBackend {
  private readonly engine: AudioEngine;
  private readonly log: RadioLog;
  private readonly fallback: SpeechVoiceBackend;
  private readonly getAnnounceMode: () => AnnounceMode;
  private readonly baseUrl: URL;
  private manifest: BoothManifest = { version: 1, clips: {} };
  private readonly buffers = new Map<string, AudioBuffer>();
  private loadPromise: Promise<void> | null = null;

  constructor(options: SampledVoiceBackendOptions) {
    this.engine = options.engine;
    this.log = options.log;
    this.fallback = options.fallback;
    this.getAnnounceMode = options.getAnnounceMode;
    this.baseUrl = options.baseUrl ?? new URL("../sounds/booth/", import.meta.url);
    if (options.manifest) this.manifest = options.manifest;
  }

  /** Fetch manifest + decode listed clips. Safe to call repeatedly. */
  async load(manifestUrl?: string): Promise<void> {
    if (this.loadPromise) return this.loadPromise;
    this.loadPromise = (async () => {
      try {
        if (!manifestUrl && Object.keys(this.manifest.clips).length === 0) {
          const url = new URL("booth-manifest.json", this.baseUrl).href;
          const response = await fetch(url);
          if (response.ok) {
            this.manifest = (await response.json()) as BoothManifest;
          }
        } else if (manifestUrl) {
          const response = await fetch(manifestUrl);
          if (response.ok) this.manifest = (await response.json()) as BoothManifest;
        }
      } catch {
        /* empty bank — fallback only */
      }

      const { ctx } = this.engine;
      await Promise.all(
        Object.entries(this.manifest.clips).map(async ([key, entry]) => {
          try {
            const fileUrl = new URL(entry.file, this.baseUrl).href;
            const response = await fetch(fileUrl);
            if (!response.ok) return;
            const raw = await response.arrayBuffer();
            const buffer = await ctx.decodeAudioData(raw.slice(0));
            this.buffers.set(key, buffer);
          } catch {
            /* leave key unloaded */
          }
        }),
      );
    })();
    return this.loadPromise;
  }

  /** Test / pipeline helper: register an already-decoded buffer under a lookup key. */
  registerBuffer(key: string, buffer: AudioBuffer, durationSec?: number): void {
    this.buffers.set(key, buffer);
    this.manifest.clips[key] = {
      file: `${key}.wav`,
      durationSec: durationSec ?? buffer.duration,
    };
  }

  get loadedClipCount(): number {
    return this.buffers.size;
  }

  estimateDuration(phrase: Phrase): number {
    const key = this.resolveKey(phrase);
    if (key) {
      const buffer = this.buffers.get(key);
      if (buffer) return buffer.duration + 0.05;
      const meta = this.manifest.clips[key];
      if (meta?.durationSec) return meta.durationSec + 0.05;
    }
    return this.fallback.estimateDuration(phrase);
  }

  speak(phrase: Phrase, atContextTime: number): SpeakHandle {
    const mode = this.getAnnounceMode();
    const speakAloud = shouldSpeakAloud(phrase) && mode !== "screen-reader";
    const key = speakAloud ? this.resolveKey(phrase) : null;
    const buffer = key ? this.buffers.get(key) ?? null : null;

    // Never hand the mic to OS Web Speech while directed samples are selected —
    // that path is louder/clearer than the cast bank and reads as "still TTS".
    // Umpire cues still use speech elsewhere. Missing clips → log only.
    if (!buffer || !key) {
      return this.speakLogOnly(phrase, atContextTime, speakAloud);
    }

    const durationSec = buffer.duration + 0.05;
    // Eric (utility) shares the off-axis color bus — distinct timbre from Brian.
    const bus: BusName =
      phrase.speaker === "color" || phrase.speaker === "utility" ? "color" : "announcer";

    if (phrase.speaker !== "umpire") {
      this.engine.duckFor(atContextTime, durationSec);
    }

    const perfTarget = this.engine.clock.audioToPerf(atContextTime);
    const delayMs = Math.max(0, perfTarget - performance.now());

    let cancelled = false;
    let voice: { stop: (when?: number) => void } | null = null;

    const timer = setTimeout(() => {
      if (cancelled) return;
      this.log.append(phrase);
      voice = playBoothBuffer(this.engine, buffer, {
        bus,
        at: this.engine.currentTime,
        gain: boothGain(phrase),
        playbackRate: boothRate(phrase),
      });
    }, delayMs);

    return {
      durationSec,
      cancel: () => {
        cancelled = true;
        clearTimeout(timer);
        voice?.stop();
      },
    };
  }

  /** Radio log without OS TTS — keeps the cast identity when a clip is missing. */
  private speakLogOnly(phrase: Phrase, atContextTime: number, appendLog: boolean): SpeakHandle {
    const durationSec = Math.min(2.2, estimateSpokenSeconds(phrase.text, phrase.energy) * 0.55 + 0.2);
    const perfTarget = this.engine.clock.audioToPerf(atContextTime);
    const delayMs = Math.max(0, perfTarget - performance.now());
    let cancelled = false;
    const timer = setTimeout(() => {
      if (cancelled || !appendLog) return;
      this.log.append(phrase);
    }, delayMs);
    return {
      durationSec,
      cancel: () => {
        cancelled = true;
        clearTimeout(timer);
      },
    };
  }

  private resolveKey(phrase: Phrase): string | null {
    // Only keys with decoded buffers — otherwise a manifest hit without audio
    // short-circuits fallbacks (e.g. call.foul.2 → call.foul.0) into TTS.
    for (const candidate of clipLookupCandidates(phrase)) {
      if (this.buffers.has(candidate)) return candidate;
    }
    return null;
  }
}

function shouldSpeakAloud(phrase: Phrase): boolean {
  return !phrase.id.startsWith("action.");
}

function boothGain(phrase: Phrase): number {
  // Cast WAVs need headroom over crowd; AM filter (when on) already attenuates.
  const base = phrase.speaker === "utility" ? 1.05 : 1.2;
  return base + phrase.energy * 0.25;
}

function boothRate(phrase: Phrase): number {
  // Tiny lift only — acted takes already carry inflection.
  return 1 + Math.max(0, phrase.energy - 0.5) * 0.04;
}

function playBoothBuffer(
  engine: AudioEngine,
  buffer: AudioBuffer,
  options: { bus: BusName; at: number; gain: number; playbackRate: number },
): { stop: (when?: number) => void } {
  const { ctx } = engine;
  const at = Math.max(options.at, ctx.currentTime);
  const source = ctx.createBufferSource();
  source.buffer = buffer;
  source.playbackRate.value = options.playbackRate;
  const gain = ctx.createGain();
  gain.gain.value = options.gain;
  source.connect(gain);
  gain.connect(engine.busInput(options.bus));
  try {
    source.start(at);
  } catch {
    /* ignore */
  }
  return {
    stop(when?: number): void {
      const t = Math.max(when ?? ctx.currentTime, ctx.currentTime);
      try {
        gain.gain.cancelScheduledValues(t);
        gain.gain.setValueAtTime(Math.max(gain.gain.value, 0), t);
        gain.gain.linearRampToValueAtTime(0, t + 0.06);
        source.stop(t + 0.08);
      } catch {
        /* already stopped */
      }
    },
  };
}
