import type { AudioEngine } from "../AudioEngine.ts";
import type { SampleId } from "../SampleBank.ts";
import type { ContactTier } from "../../timing/SwingJudge.ts";
import { FIELD_POSITIONS, applyEnvelope, noiseBurst, spatialPanner } from "./shared.ts";
import { clamp } from "../../timing/Timeline.ts";

/**
 * Bat on ball — or bat on nothing.
 *
 * Prefers decoded wooden-bat clips from SampleBank; falls back to the original
 * layered synth (click + ring + body) when samples aren't loaded.
 */

export interface BatContactSpec {
  at: number;
  tier: ContactTier;
  /** 0..1 contact quality from SwingJudge. */
  quality: number;
  /**
   * Where the ball went, -1 hard pull to +1 opposite field. Derived from the sign
   * of the timing error: early swings get out in front and pull.
   */
  spray: number;
}

const TIER_SAMPLES: Record<Exclude<ContactTier, "miss">, readonly SampleId[]> = {
  solid: ["bat-solid-1", "bat-solid-2"],
  weak: ["bat-weak-1", "bat-solid-2"],
  "foul-tip": ["bat-foul-1", "bat-weak-1"],
};

const TIER_GAIN: Record<Exclude<ContactTier, "miss">, number> = {
  solid: 0.95,
  weak: 0.7,
  "foul-tip": 0.45,
};

export function playBatContact(engine: AudioEngine, spec: BatContactSpec): void {
  if (spec.tier === "miss") {
    playWhiff(engine, spec.at);
    return;
  }

  const quality = clamp(spec.quality, 0, 1);
  const sprayPan = clamp(spec.spray, -1, 1) * 0.6;
  const id = engine.samples.pick(TIER_SAMPLES[spec.tier]);
  if (id) {
    const rate =
      spec.tier === "solid"
        ? 0.96 + quality * 0.08
        : spec.tier === "weak"
          ? 0.88 + quality * 0.06
          : 1.15 + quality * 0.1;
    const played = engine.samples.play(engine, id, {
      bus: "field",
      at: spec.at,
      gain: TIER_GAIN[spec.tier] * (1.1 + quality * 0.5),
      pan: sprayPan,
      playbackRate: rate,
      fadeIn: 0,
    });
    if (played) {
      // Light synth under the clip so the crack still reads if the sample is dull.
      playBatSynth(engine, spec, quality * 0.45, sprayPan, 0.35);
      return;
    }
  }

  playBatSynth(engine, spec, quality, sprayPan);
}

function playBatSynth(
  engine: AudioEngine,
  spec: BatContactSpec,
  quality: number,
  sprayPan: number,
  levelScale = 1,
): void {
  if (spec.tier === "miss") return;
  const { ctx } = engine;
  const tier = spec.tier;

  const panner = spatialPanner(ctx, FIELD_POSITIONS.plate);
  const spray = ctx.createStereoPanner();
  spray.pan.value = sprayPan;
  panner.connect(spray);
  spray.connect(engine.busInput("field"));

  const tone = TIER_TONE[tier];

  noiseBurst(engine, panner, {
    at: spec.at,
    duration: tone.clickDuration,
    color: "white",
    frequency: tone.clickFreq * (0.85 + quality * 0.3),
    q: 0.8,
    peak: tone.clickPeak * (0.6 + quality * 0.5) * levelScale,
    attack: 0.0008,
  });

  const ring = ctx.createOscillator();
  ring.type = "triangle";
  const ringFreq = tone.ringFreq * (0.9 + quality * 0.25);
  ring.frequency.setValueAtTime(ringFreq, spec.at);
  ring.frequency.exponentialRampToValueAtTime(ringFreq * 0.82, spec.at + tone.ringDecay);

  const ringGain = ctx.createGain();
  ring.connect(ringGain);
  ringGain.connect(panner);
  const ringEnd = applyEnvelope(ringGain.gain, {
    at: spec.at,
    attack: 0.0012,
    decay: tone.ringDecay,
    peak: tone.ringPeak * (0.5 + quality * 0.6) * levelScale,
  });
  ring.start(spec.at);
  ring.stop(ringEnd + 0.05);

  if (tone.bodyPeak > 0) {
    const body = ctx.createOscillator();
    body.type = "sine";
    body.frequency.setValueAtTime(180, spec.at);
    body.frequency.exponentialRampToValueAtTime(110, spec.at + 0.09);
    const bodyGain = ctx.createGain();
    body.connect(bodyGain);
    bodyGain.connect(panner);
    const bodyEnd = applyEnvelope(bodyGain.gain, {
      at: spec.at,
      attack: 0.002,
      decay: 0.1,
      peak: tone.bodyPeak * (0.4 + quality * 0.7) * levelScale,
    });
    body.start(spec.at);
    body.stop(bodyEnd + 0.05);
  }
}

interface ToneSpec {
  clickFreq: number;
  clickDuration: number;
  clickPeak: number;
  ringFreq: number;
  ringDecay: number;
  ringPeak: number;
  bodyPeak: number;
}

const TIER_TONE: Record<Exclude<ContactTier, "miss">, ToneSpec> = {
  solid: {
    clickFreq: 2100,
    clickDuration: 0.022,
    clickPeak: 0.95,
    ringFreq: 900,
    ringDecay: 0.1,
    ringPeak: 0.5,
    bodyPeak: 0.45,
  },
  weak: {
    clickFreq: 1100,
    clickDuration: 0.035,
    clickPeak: 0.6,
    ringFreq: 460,
    ringDecay: 0.14,
    ringPeak: 0.38,
    bodyPeak: 0.22,
  },
  "foul-tip": {
    clickFreq: 3600,
    clickDuration: 0.012,
    clickPeak: 0.42,
    ringFreq: 1800,
    ringDecay: 0.035,
    ringPeak: 0.14,
    bodyPeak: 0,
  },
};

/** Bat through empty air: a fast downward noise sweep, no impact at all. */
function playWhiff(engine: AudioEngine, at: number): void {
  const { ctx } = engine;
  const panner = spatialPanner(ctx, FIELD_POSITIONS.plate);
  panner.connect(engine.busInput("field"));

  const source = engine.noise.source("white");
  const band = ctx.createBiquadFilter();
  band.type = "bandpass";
  band.Q.value = 1.6;
  band.frequency.setValueAtTime(1800, at);
  band.frequency.exponentialRampToValueAtTime(420, at + 0.13);

  const gain = ctx.createGain();
  source.connect(band);
  band.connect(gain);
  gain.connect(panner);

  const end = applyEnvelope(gain.gain, { at, attack: 0.012, decay: 0.12, peak: 0.35 });
  source.start(at, engine.noise.randomOffset(0.3));
  source.stop(end + 0.05);
}
