import type { AudioEngine, BusName } from "./AudioEngine.ts";

/**
 * SampleBank — decoded one-shots and loops from /public/sounds.
 *
 * Synth voices remain the fallback when a clip is missing or still loading.
 */

export type SampleId =
  | "bat-solid-1"
  | "bat-solid-2"
  | "bat-weak-1"
  | "bat-foul-1"
  | "glove-1"
  | "glove-2"
  | "glove-3"
  | "glove-4"
  | "crowd-bed"
  | "crowd-cheer"
  | "crowd-clap"
  | "crowd-roar"
  | "vendor-beer"
  | "vendor-dogs"
  | "vendor-programs"
  | "umpire-strike"
  | "umpire-ball"
  | "umpire-out";

const SOUND_BASE_URL = new URL("../sounds/", import.meta.url);
const soundUrl = (fileName: string): string => new URL(fileName, SOUND_BASE_URL).href;

const MANIFEST: Record<SampleId, string> = {
  "bat-solid-1": soundUrl("bat-solid-1.wav"),
  "bat-solid-2": soundUrl("bat-solid-2.wav"),
  "bat-weak-1": soundUrl("bat-weak-1.wav"),
  "bat-foul-1": soundUrl("bat-foul-1.wav"),
  "glove-1": soundUrl("glove-1.wav"),
  "glove-2": soundUrl("glove-2.wav"),
  "glove-3": soundUrl("glove-3.wav"),
  "glove-4": soundUrl("glove-4.wav"),
  "crowd-bed": soundUrl("crowd-bed.wav"),
  "crowd-cheer": soundUrl("crowd-cheer.wav"),
  "crowd-clap": soundUrl("crowd-clap.wav"),
  "crowd-roar": soundUrl("crowd-roar.wav"),
  "vendor-beer": soundUrl("vendor-beer.wav"),
  "vendor-dogs": soundUrl("vendor-dogs.wav"),
  "vendor-programs": soundUrl("vendor-programs.wav"),
  "umpire-strike": soundUrl("umpire-strike.wav"),
  "umpire-ball": soundUrl("umpire-ball.wav"),
  "umpire-out": soundUrl("umpire-out.wav"),
};

/** Every SampleId the runtime expects — used by publish sync / manifest checks. */
export const SAMPLE_IDS = Object.keys(MANIFEST) as SampleId[];

export interface PlaySampleOptions {
  bus?: BusName;
  /** If set, connect here instead of a named bus (for beds under a GainNode). */
  destination?: AudioNode;
  at?: number;
  gain?: number;
  pan?: number;
  playbackRate?: number;
  loop?: boolean;
  /** Offset into the buffer (seconds). */
  offset?: number;
  /** How long to play before stopping (seconds). Omit for full buffer / loop. */
  duration?: number;
  fadeIn?: number;
  fadeOut?: number;
}

export interface SampleVoice {
  stop(when?: number): void;
  readonly source: AudioBufferSourceNode;
  readonly gain: GainNode;
}

export class SampleBank {
  private readonly buffers = new Map<SampleId, AudioBuffer>();
  private loadPromise: Promise<void> | null = null;
  private _ready = false;

  get ready(): boolean {
    return this._ready;
  }

  /** Decode every clip. Safe to call more than once. */
  load(ctx: AudioContext): Promise<void> {
    if (this.loadPromise) return this.loadPromise;
    this.loadPromise = (async () => {
      const entries = Object.entries(MANIFEST) as [SampleId, string][];
      await Promise.all(
        entries.map(async ([id, url]) => {
          try {
            const response = await fetch(url);
            if (!response.ok) return;
            const raw = await response.arrayBuffer();
            const buffer = await ctx.decodeAudioData(raw.slice(0));
            this.buffers.set(id, buffer);
          } catch {
            // Leave that id unloaded; callers fall back to synth.
          }
        }),
      );
      this._ready = this.buffers.size > 0;
    })();
    return this.loadPromise;
  }

  has(id: SampleId): boolean {
    return this.buffers.has(id);
  }

  get(id: SampleId): AudioBuffer | null {
    return this.buffers.get(id) ?? null;
  }

  pick(ids: readonly SampleId[], rng: () => number = Math.random): SampleId | null {
    const available = ids.filter((id) => this.has(id));
    if (available.length === 0) return null;
    const index = Math.min(available.length - 1, Math.floor(rng() * available.length));
    return available[index] ?? null;
  }

  play(engine: AudioEngine, id: SampleId, options: PlaySampleOptions = {}): SampleVoice | null {
    const buffer = this.buffers.get(id);
    if (!buffer) return null;

    const { ctx } = engine;
    // Never schedule in the past — stale `at` leaves gain ramps stuck near zero.
    const at = Math.max(options.at ?? ctx.currentTime, ctx.currentTime);
    const gainValue = Math.max(0, options.gain ?? 1);
    const rate = options.playbackRate ?? 1;

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.loop = options.loop ?? false;
    source.playbackRate.value = rate;

    const gain = ctx.createGain();
    // Default is an immediate attack — bat/glove cracks live in the first milliseconds.
    // Beds/stingers that need a soft open pass fadeIn explicitly.
    const fadeIn = options.fadeIn ?? 0;
    if (fadeIn <= 0) {
      gain.gain.value = gainValue;
      gain.gain.setValueAtTime(gainValue, at);
    } else {
      gain.gain.setValueAtTime(0, at);
      gain.gain.linearRampToValueAtTime(gainValue, at + fadeIn);
    }

    // Source must feed the gain — without this the buffer plays into silence.
    source.connect(gain);

    let dest: AudioNode = gain;
    if (options.pan !== undefined) {
      const panner = ctx.createStereoPanner();
      panner.pan.value = options.pan;
      gain.connect(panner);
      dest = panner;
    }
    dest.connect(options.destination ?? engine.busInput(options.bus ?? "field"));

    const maxOffset = Math.max(0, buffer.duration - 0.05);
    const offset = Math.min(Math.max(0, options.offset ?? 0), maxOffset);
    try {
      if (options.duration !== undefined) {
        source.start(at, offset, options.duration);
      } else {
        source.start(at, offset);
      }
    } catch {
      return null;
    }

    if (options.fadeOut && options.duration !== undefined) {
      const fadeStart = at + options.duration - options.fadeOut;
      if (fadeStart > at) {
        gain.gain.setValueAtTime(gainValue, fadeStart);
        gain.gain.linearRampToValueAtTime(0, at + options.duration);
      }
    }

    return {
      source,
      gain,
      stop(when?: number): void {
        const t = Math.max(when ?? ctx.currentTime, ctx.currentTime);
        try {
          gain.gain.cancelScheduledValues(t);
          gain.gain.setValueAtTime(Math.max(gain.gain.value, 0), t);
          gain.gain.linearRampToValueAtTime(0, t + 0.08);
          source.stop(t + 0.1);
        } catch {
          // already stopped
        }
      },
    };
  }
}
