import type { AudioEngine } from "../AudioEngine.ts";
import { FIELD_POSITIONS, applyEnvelope, spatialPanner } from "./shared.ts";

/**
 * The umpire — a quiet field bark plus clear spoken words.
 *
 * The formant shout is only presence: a short spatial thud from behind the plate
 * so the call still feels like it comes from the diamond. The intelligible words
 * ("Strike!", "Ball!", …) are spoken through Web Speech via the commentary queue.
 * Peaks stay low so the bark does not drown the spoken call.
 */

export type UmpireCall = "strike" | "ball" | "strike-three" | "out" | "foul";

/** Clear lines for the speech backend / radio log. */
export const UMPIRE_WORDS: Record<UmpireCall, string> = {
  strike: "Strike!",
  ball: "Ball!",
  "strike-three": "Strike three!",
  out: "Out!",
  foul: "Foul!",
};

interface Syllable {
  /** Seconds from the start of the call. */
  offset: number;
  duration: number;
  startHz: number;
  endHz: number;
  /** First formant centre — the vowel colour. */
  formant: number;
  peak: number;
}

/** Soft spatial accent — loud enough to place, quiet enough to sit under speech. */
const CALLS: Record<UmpireCall, readonly Syllable[]> = {
  strike: [
    { offset: 0, duration: 0.11, startHz: 190, endHz: 230, formant: 720, peak: 0.16 },
    { offset: 0.12, duration: 0.22, startHz: 240, endHz: 150, formant: 620, peak: 0.2 },
  ],
  "strike-three": [
    { offset: 0, duration: 0.12, startHz: 200, endHz: 250, formant: 760, peak: 0.18 },
    { offset: 0.14, duration: 0.18, startHz: 260, endHz: 290, formant: 700, peak: 0.22 },
    { offset: 0.34, duration: 0.32, startHz: 290, endHz: 140, formant: 560, peak: 0.24 },
  ],
  ball: [{ offset: 0, duration: 0.18, startHz: 168, endHz: 150, formant: 560, peak: 0.14 }],
  out: [{ offset: 0, duration: 0.24, startHz: 225, endHz: 150, formant: 660, peak: 0.18 }],
  foul: [{ offset: 0, duration: 0.15, startHz: 195, endHz: 168, formant: 640, peak: 0.14 }],
};

export function playUmpireCall(engine: AudioEngine, call: UmpireCall, at: number): number {
  const sampleId =
    call === "strike" || call === "strike-three"
      ? "umpire-strike"
      : call === "ball"
        ? "umpire-ball"
        : call === "out"
          ? "umpire-out"
          : null;
  if (sampleId && engine.samples.has(sampleId)) {
    engine.samples.play(engine, sampleId, {
      bus: "field",
      at,
      gain: call === "strike-three" ? 0.55 : 0.42,
      fadeIn: 0.005,
      fadeOut: 0.15,
      duration: call === "strike-three" ? 0.55 : 0.35,
    });
    // Still layer a soft synth bark under the sample for spatial place.
  }

  const { ctx } = engine;

  const panner = spatialPanner(ctx, FIELD_POSITIONS.umpire);
  const shout = ctx.createWaveShaper();
  shout.curve = rasp();
  shout.oversample = "2x";
  shout.connect(panner);
  panner.connect(engine.busInput("field"));

  let end = at;
  for (const syllable of CALLS[call]) {
    const peakScale = sampleId && engine.samples.has(sampleId) ? 0.45 : 1;
    end = Math.max(
      end,
      playSyllable(engine, shout, at + syllable.offset, { ...syllable, peak: syllable.peak * peakScale }),
    );
  }
  return end;
}

/**
 * How long to hold the booth for a spoken umpire call.
 * Longer than the formant bark — speech needs the airtime.
 */
export function umpireCallDuration(call: UmpireCall): number {
  switch (call) {
    case "strike-three":
      return 1.05;
    case "out":
      return 0.7;
    case "foul":
      return 0.55;
    default:
      return 0.65;
  }
}

function playSyllable(engine: AudioEngine, destination: AudioNode, at: number, spec: Syllable): number {
  const { ctx } = engine;

  const voice = ctx.createOscillator();
  voice.type = "sawtooth";
  voice.frequency.setValueAtTime(spec.startHz, at);
  voice.frequency.exponentialRampToValueAtTime(Math.max(spec.endHz, 20), at + spec.duration);

  // Two formants is the minimum that reads as a human vowel rather than a buzz.
  const f1 = ctx.createBiquadFilter();
  f1.type = "bandpass";
  f1.frequency.value = spec.formant;
  f1.Q.value = 4;

  const f2 = ctx.createBiquadFilter();
  f2.type = "bandpass";
  f2.frequency.value = spec.formant * 2.4;
  f2.Q.value = 6;

  const f2Gain = ctx.createGain();
  f2Gain.gain.value = 0.45;

  const gain = ctx.createGain();

  voice.connect(f1);
  voice.connect(f2);
  f2.connect(f2Gain);
  f1.connect(gain);
  f2Gain.connect(gain);
  gain.connect(destination);

  // Breath: a little noise riding the same envelope keeps it from sounding synthetic.
  const breath = engine.noise.source("white");
  const breathBand = ctx.createBiquadFilter();
  breathBand.type = "bandpass";
  breathBand.frequency.value = spec.formant * 1.8;
  breathBand.Q.value = 1.2;
  const breathGain = ctx.createGain();
  breath.connect(breathBand);
  breathBand.connect(breathGain);
  breathGain.connect(destination);

  const end = applyEnvelope(gain.gain, {
    at,
    attack: 0.02,
    hold: spec.duration * 0.4,
    decay: spec.duration * 0.5,
    peak: spec.peak,
    sustain: 0.8,
  });
  applyEnvelope(breathGain.gain, {
    at,
    attack: 0.02,
    hold: spec.duration * 0.4,
    decay: spec.duration * 0.5,
    peak: spec.peak * 0.18,
    sustain: 0.8,
  });

  voice.start(at);
  voice.stop(end + 0.05);
  breath.start(at, engine.noise.randomOffset(spec.duration + 0.2));
  breath.stop(end + 0.05);
  return end;
}

/** Asymmetric clipping — cheap vocal-cord grit. */
function rasp(samples = 1024): Float32Array<ArrayBuffer> {
  const curve = new Float32Array(new ArrayBuffer(samples * Float32Array.BYTES_PER_ELEMENT));
  for (let i = 0; i < samples; i++) {
    const x = (i / (samples - 1)) * 2 - 1;
    curve[i] = Math.tanh(x * 3) * (x > 0 ? 1 : 0.82);
  }
  return curve;
}
