/**
 * NoiseFactory — shared noise buffers.
 *
 * Almost every sound in this game is noise-derived: the scuff of a cleat, the
 * whoosh of a release, the crack of a bat, twenty thousand people murmuring.
 * Allocating a fresh AudioBuffer per event would churn several megabytes a second
 * during a crowd swell and produce audible GC hitches — exactly during the moments
 * the game most wants to sound good.
 *
 * So: generate each colour once at startup, then play windowed slices from random
 * offsets. Two hits of the same buffer at different offsets are perceptually
 * independent, which is all we need.
 */

export type NoiseColor = "white" | "pink" | "brown";

const BUFFER_SECONDS = 4;

export class NoiseFactory {
  private readonly ctx: BaseAudioContext;
  private readonly cache = new Map<NoiseColor, AudioBuffer>();

  constructor(ctx: BaseAudioContext) {
    this.ctx = ctx;
  }

  /** Pre-generate every colour so the first pitch doesn't pay the cost. */
  warmUp(): void {
    this.buffer("white");
    this.buffer("pink");
    this.buffer("brown");
  }

  buffer(color: NoiseColor): AudioBuffer {
    const cached = this.cache.get(color);
    if (cached) return cached;

    const length = Math.floor(this.ctx.sampleRate * BUFFER_SECONDS);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    fill(data, color);
    this.cache.set(color, buffer);
    return buffer;
  }

  /**
   * A source node playing from a random offset, ready to be connected.
   * The caller owns starting and stopping it.
   */
  source(color: NoiseColor, options: { loop?: boolean; playbackRate?: number } = {}): AudioBufferSourceNode {
    const node = this.ctx.createBufferSource();
    node.buffer = this.buffer(color);
    node.loop = options.loop ?? false;
    if (options.playbackRate !== undefined) node.playbackRate.value = options.playbackRate;
    return node;
  }

  /** Random start offset, kept clear of the tail so short grains never run dry. */
  randomOffset(grainSeconds = 0.5): number {
    return Math.random() * Math.max(0, BUFFER_SECONDS - grainSeconds);
  }
}

function fill(data: Float32Array, color: NoiseColor): void {
  switch (color) {
    case "white": {
      for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
      return;
    }
    case "pink": {
      // Paul Kellet's economy pink-noise filter: six one-pole sections summed.
      // Cheap, and the 1/f slope is accurate enough to sit under a crowd bed.
      let b0 = 0;
      let b1 = 0;
      let b2 = 0;
      let b3 = 0;
      let b4 = 0;
      let b5 = 0;
      let b6 = 0;
      for (let i = 0; i < data.length; i++) {
        const white = Math.random() * 2 - 1;
        b0 = 0.99886 * b0 + white * 0.0555179;
        b1 = 0.99332 * b1 + white * 0.0750759;
        b2 = 0.969 * b2 + white * 0.153852;
        b3 = 0.8665 * b3 + white * 0.3104856;
        b4 = 0.55 * b4 + white * 0.5329522;
        b5 = -0.7616 * b5 - white * 0.016898;
        data[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362) * 0.11;
        b6 = white * 0.115926;
      }
      return;
    }
    case "brown": {
      let last = 0;
      for (let i = 0; i < data.length; i++) {
        const white = Math.random() * 2 - 1;
        last = (last + 0.02 * white) / 1.02;
        data[i] = last * 3.5;
      }
      return;
    }
  }
}
