import type { AudioEngine } from "../audio/AudioEngine.ts";

/**
 * Diagnostics — the panel that tells you whether the engine is lying to you.
 *
 * On a timing game, "it feels 40 ms late" and "it *is* 40 ms late" are
 * indistinguishable from the outside, and both are indistinguishable from "your
 * headphones are 40 ms late". This panel separates them, and it exists from the
 * first commit rather than being retrofitted after someone spends a day chasing a
 * bug that was a Bluetooth codec all along.
 *
 * What to look for:
 *   - Clock jitter above ~15 ms means the correlation is unreliable; suspect a
 *     saturated main thread before suspecting the judge.
 *   - A histogram centred off zero means a *constant* bias — run calibration.
 *   - A histogram that drifts across a session means the clock offset is being
 *     tracked badly, which is a ClockBridge problem, not a player problem.
 */

const BIN_COUNT = 21;
const BIN_WIDTH_MS = 10;
const HALF_RANGE_MS = (BIN_COUNT * BIN_WIDTH_MS) / 2;
const HISTORY_LIMIT = 60;

export class Diagnostics {
  private readonly root: HTMLElement;
  private readonly engine: AudioEngine;
  private readonly getCalibrationMs: () => number;
  private readonly getLeverage: (() => { leverage: number; excitement: number }) | undefined;
  private readonly deltas: number[] = [];
  private timer: ReturnType<typeof setInterval> | null = null;

  constructor(
    root: HTMLElement,
    engine: AudioEngine,
    getCalibrationMs: () => number,
    getLeverage?: () => { leverage: number; excitement: number },
  ) {
    this.root = root;
    this.engine = engine;
    this.getCalibrationMs = getCalibrationMs;
    this.getLeverage = getLeverage;
  }

  /** Record a judged swing. Only swings — takes carry no timing information. */
  recordSwing(deltaMs: number): void {
    this.deltas.push(deltaMs);
    if (this.deltas.length > HISTORY_LIMIT) this.deltas.shift();
    this.render();
  }

  start(): void {
    if (this.timer !== null) return;
    this.render();
    this.timer = setInterval(() => this.render(), 400);
  }

  stop(): void {
    if (this.timer === null) return;
    clearInterval(this.timer);
    this.timer = null;
  }

  reset(): void {
    this.deltas.length = 0;
    this.render();
  }

  private render(): void {
    const ctx = this.engine.ctx;
    const clock = this.engine.clock.stats();

    const latency = this.group("Latency", [
      ["base", ms(ctx.baseLatency)],
      ["output", ms((ctx as AudioContext & { outputLatency?: number }).outputLatency)],
      ["calibration", `${signed(this.getCalibrationMs())} ms`],
      ["sample rate", `${(ctx.sampleRate / 1000).toFixed(1)} kHz`],
    ]);

    const bridge = this.group("Clock bridge", [
      ["source", clock.source],
      ["offset", `${clock.offsetMs.toFixed(1)} ms`],
      ["jitter", `${clock.jitterMs.toFixed(1)} ms`],
      ["samples", String(clock.sampleCount)],
    ]);

    const swings = this.group("Swings", this.swingRows());

    const game = this.getLeverage
      ? this.group("Game", (() => {
          const { leverage, excitement } = this.getLeverage!();
          return [
            ["leverage", leverage.toFixed(2)],
            ["crowd level", `${excitement} / 5`],
          ] as Array<[string, string]>;
        })())
      : null;

    this.root.replaceChildren(
      ...(game ? [game] : []),
      latency,
      bridge,
      swings,
      this.histogram(),
    );
  }

  private swingRows(): Array<[string, string, (string | undefined)?]> {
    if (this.deltas.length === 0) {
      return [["last", "--"], ["mean", "--"], ["spread", "--"], ["count", "0"]];
    }
    const last = this.deltas[this.deltas.length - 1] as number;
    const mean = this.deltas.reduce((a, b) => a + b, 0) / this.deltas.length;
    const spread = Math.max(...this.deltas) - Math.min(...this.deltas);

    return [
      ["last", `${signed(last)} ms ${label(last)}`, toneClass(last)],
      ["mean", `${signed(mean)} ms`, Math.abs(mean) > 20 ? "val-late" : undefined],
      ["spread", `${spread.toFixed(0)} ms`],
      ["count", String(this.deltas.length)],
    ];
  }

  private group(title: string, rows: Array<[string, string, (string | undefined)?]>): HTMLElement {
    const wrap = document.createElement("dl");
    wrap.className = "diag-group";

    const heading = document.createElement("div");
    heading.className = "diag-row";
    const key = document.createElement("dt");
    key.textContent = title.toUpperCase();
    heading.append(key);
    wrap.append(heading);

    for (const [name, value, tone] of rows) {
      const row = document.createElement("div");
      row.className = "diag-row";
      const dt = document.createElement("dt");
      dt.textContent = name;
      const dd = document.createElement("dd");
      dd.textContent = value;
      if (tone) dd.className = tone;
      row.append(dt, dd);
      wrap.append(row);
    }
    return wrap;
  }

  /** Signed error distribution. The shape is the diagnosis. */
  private histogram(): HTMLElement {
    const bins = new Array<number>(BIN_COUNT).fill(0);
    for (const delta of this.deltas) {
      const index = Math.floor((delta + HALF_RANGE_MS) / BIN_WIDTH_MS);
      const clamped = Math.min(BIN_COUNT - 1, Math.max(0, index));
      bins[clamped] = (bins[clamped] ?? 0) + 1;
    }
    const peak = Math.max(1, ...bins);
    const centre = (BIN_COUNT - 1) / 2;

    const wrap = document.createElement("div");
    wrap.className = "diag-group";

    const chart = document.createElement("div");
    chart.className = "histogram";
    chart.setAttribute("aria-hidden", "true");
    bins.forEach((count, index) => {
      const bar = document.createElement("div");
      bar.className = Math.abs(index - centre) <= 1 ? "histogram-bin histogram-bin--center" : "histogram-bin";
      bar.style.height = `${(count / peak) * 100}%`;
      chart.append(bar);
    });

    const axis = document.createElement("div");
    axis.className = "histogram-axis";
    for (const text of [`-${HALF_RANGE_MS}`, "early | late", `+${HALF_RANGE_MS}`]) {
      const span = document.createElement("span");
      span.textContent = text;
      axis.append(span);
    }

    wrap.append(chart, axis);
    return wrap;
  }
}

function ms(value: number | undefined): string {
  if (typeof value !== "number" || !Number.isFinite(value)) return "n/a";
  return `${(value * 1000).toFixed(1)} ms`;
}

function signed(value: number): string {
  return `${value >= 0 ? "+" : ""}${value.toFixed(1)}`;
}

function label(delta: number): string {
  const magnitude = Math.abs(delta);
  if (magnitude < 30) return "perfect";
  return delta < 0 ? "early" : "late";
}

function toneClass(delta: number): string {
  const magnitude = Math.abs(delta);
  if (magnitude < 30) return "val-perfect";
  return delta < 0 ? "val-early" : "val-late";
}
