import type { GameSnapshot } from "../game/GameState.ts";
import { formatCount, formatScoreline } from "../game/GameState.ts";
import { formatBats, formatThrows } from "../game/Teams.ts";

/**
 * Compact always-visible score summary for screen readers and glanceable text.
 */
export class LiveScore {
  private readonly root: HTMLElement;
  private lastText = "";

  constructor(root: HTMLElement) {
    this.root = root;
    this.root.setAttribute("role", "status");
    this.root.setAttribute("aria-live", "polite");
    this.root.setAttribute("aria-atomic", "true");
  }

  render(snapshot: GameSnapshot): void {
    const text = summarize(snapshot);
    if (text === this.lastText) return;
    this.lastText = text;
    this.root.textContent = text;
  }
}

export function summarize(snapshot: GameSnapshot): string {
  if (snapshot.gameOver) {
    return `Final ${formatScoreline(snapshot.score)}. ${snapshot.awayTeam} ${snapshot.score.away}, ${snapshot.homeTeam} ${snapshot.score.home}.`;
  }

  const half = snapshot.half === "top" ? "Top" : "Bottom";
  const outs = snapshot.outs === 1 ? "1 out" : `${snapshot.outs} outs`;
  const bases = describeBases(snapshot.bases);
  return [
    `${half} ${snapshot.inning}.`,
    `Score ${snapshot.awayTeam} ${snapshot.score.away}, ${snapshot.homeTeam} ${snapshot.score.home}.`,
    `${outs}, count ${formatCount(snapshot.balls, snapshot.strikes)}.`,
    bases,
    `At bat: ${snapshot.batter} (${formatBats(snapshot.batter)}) for ${snapshot.battingTeam}.`,
    `Pitching: ${snapshot.pitcher} (${formatThrows(snapshot.pitcher)}) for ${snapshot.fieldingTeam}.`,
  ].join(" ");
}

function describeBases(bases: GameSnapshot["bases"]): string {
  const on: string[] = [];
  if (bases.first) on.push("first");
  if (bases.second) on.push("second");
  if (bases.third) on.push("third");
  if (on.length === 0) return "Bases empty.";
  if (on.length === 3) return "Bases loaded.";
  return `Runner${on.length > 1 ? "s" : ""} on ${on.join(" and ")}.`;
}
