/**
 * SwingInput — captures the swing and stamps it as accurately as the platform allows.
 *
 * Two details here matter more than the amount of code suggests.
 *
 * First, we read `event.timeStamp` rather than calling `performance.now()` inside
 * the handler. The browser stamps the event when it creates it, which is closer to
 * the physical keypress than the moment our listener happens to run. On a busy main
 * thread that difference is regularly 5–20 ms — a meaningful slice of a 30 ms window.
 *
 * Second, that stamp is not trustworthy everywhere, so it is range-checked before
 * use. Some environments (old WebKit, certain automation drivers, synthetic events
 * built by hand) emit epoch-based milliseconds, which are ~1.7e12 and would put
 * every swing fifty years late.
 */

export type SwingSource = "keyboard" | "pointer" | "synthetic";

export interface SwingEvent {
  /** Performance-timeline milliseconds. */
  perfMs: number;
  source: SwingSource;
}

export type SwingHandler = (event: SwingEvent) => void;

export interface SwingInputOptions {
  /** Where to listen. Defaults to `window`. */
  target?: EventTarget;
  /** Injectable clock, for tests. */
  now?: () => number;
  /** Also accept pointer taps, for touch. Default true. */
  acceptPointer?: boolean;
}

export class SwingInput {
  private readonly target: EventTarget;
  private readonly now: () => number;
  private handler: SwingHandler | null = null;
  private disposed = false;

  /** Presses that arrived while no pitch was live. Surfaced as a "flinches" stat. */
  private _ignoredPresses = 0;

  private readonly onKeyDown = (event: Event): void => {
    const key = event as KeyboardEvent;
    if (key.code !== "Space" && key.key !== " ") return;
    if (isTextEntry(key.target)) return;

    // When a pitch is live, Space is always the swing/release — never re-click Pause.
    // When idle, let Space activate the focused button (Skip calibration, Start at-bat,
    // etc.). Stealing Space while unarmed left keyboard/SR users stuck on a disabled
    // "Start at-bat" after Play Ball focused "I know my latency".
    if (!this.handler && isActivatableControl(key.target)) {
      return;
    }

    // Swallow otherwise so Space does not scroll the page between pitches.
    key.preventDefault();
    if (key.repeat) return;
    this.accept(stampOf(key, this.now), "keyboard");
  };

  private readonly onPointerDown = (event: Event): void => {
    // Taps on real controls are for those controls, not for swinging.
    if (isInteractiveControl(event.target)) return;
    this.accept(stampOf(event, this.now), "pointer");
  };

  constructor(options: SwingInputOptions = {}) {
    this.target = options.target ?? globalThis.window;
    this.now = options.now ?? (() => performance.now());

    this.target.addEventListener("keydown", this.onKeyDown);
    if (options.acceptPointer !== false) {
      this.target.addEventListener("pointerdown", this.onPointerDown);
    }
  }

  /**
   * Accept exactly one swing, then disarm.
   *
   * Returns a cancel function for the case where the pitch resolves as a take and
   * a late press must no longer count.
   */
  arm(handler: SwingHandler): () => void {
    this.handler = handler;
    return () => {
      if (this.handler === handler) this.handler = null;
    };
  }

  disarm(): void {
    this.handler = null;
  }

  get isArmed(): boolean {
    return this.handler !== null;
  }

  get ignoredPresses(): number {
    return this._ignoredPresses;
  }

  /**
   * Feed a swing in directly. Used by the automated timing harness so it can
   * exercise this exact code path — arming, one-shot semantics and all — without
   * synthesising DOM events whose timestamps we would then have to distrust.
   */
  injectSwing(perfMs: number): void {
    this.accept(perfMs, "synthetic");
  }

  private accept(perfMs: number, source: SwingSource): void {
    if (this.disposed) return;
    const handler = this.handler;
    if (!handler) {
      this._ignoredPresses++;
      return;
    }
    // One-shot: clear before dispatching so a handler that re-arms us (the next
    // pitch starting immediately) isn't clobbered on the way out.
    this.handler = null;
    handler({ perfMs, source });
  }

  dispose(): void {
    this.disposed = true;
    this.handler = null;
    this.target.removeEventListener("keydown", this.onKeyDown);
    this.target.removeEventListener("pointerdown", this.onPointerDown);
  }
}

/**
 * Range-check `event.timeStamp` and fall back to the wall clock when it looks wrong.
 * Anything not plausibly on the current performance timeline is rejected.
 */
export function stampOf(event: { timeStamp?: number }, now: () => number): number {
  const stamp = event.timeStamp;
  const current = now();
  if (typeof stamp !== "number" || !Number.isFinite(stamp) || stamp <= 0) return current;
  if (stamp > current + 1000) return current; // epoch-based, or a clock from the future
  if (stamp < current - 5000) return current; // impossibly stale
  return stamp;
}

/**
 * Only somewhere the player could be typing. Deliberately excludes buttons,
 * checkboxes and sliders: those hold focus after a click, and treating them as
 * "the user is busy" would disable swinging for the rest of the session.
 */
export function isTextEntry(target: EventTarget | null): boolean {
  const element = target as HTMLElement | null;
  if (!element || typeof element.tagName !== "string") return false;
  if (element.isContentEditable) return true;

  const tag = element.tagName;
  if (tag === "TEXTAREA" || tag === "SELECT") return true;
  if (tag !== "INPUT") return false;

  const type = (element as HTMLInputElement).type;
  return type !== "range" && type !== "checkbox" && type !== "radio" && type !== "button";
}

/** Any control a tap should operate rather than swing at. */
function isInteractiveControl(target: EventTarget | null): boolean {
  const element = target as HTMLElement | null;
  if (!element || typeof element.tagName !== "string") return false;
  // Explicit timing targets (calibration pad, Swing/Release) *are* swings.
  if (element.closest?.("[data-timing-action]")) return false;
  const tag = element.tagName;
  return (
    tag === "BUTTON" ||
    tag === "INPUT" ||
    tag === "SELECT" ||
    tag === "TEXTAREA" ||
    tag === "LABEL" ||
    tag === "A"
  );
}

/**
 * Focused controls that should keep Space = Activate when no pitch is armed.
 * Timing-action buttons are excluded so Space on Swing still goes through injectSwing.
 */
export function isActivatableControl(target: EventTarget | null): boolean {
  const element = target as HTMLElement | null;
  if (!element || typeof element.tagName !== "string") return false;
  if (element.closest?.("[data-timing-action]")) return false;
  const tag = element.tagName;
  if (tag === "BUTTON") return !(element as HTMLButtonElement).disabled;
  if (tag === "A") return Boolean((element as HTMLAnchorElement).href);
  if (tag === "SUMMARY") return true;
  if (tag !== "INPUT") return false;
  const type = (element as HTMLInputElement).type;
  return type === "button" || type === "submit" || type === "reset" || type === "checkbox" || type === "radio";
}
