/**
 * Composition root and at-bat loop.
 *
 * Everything above this file is testable in isolation; this is the one place that
 * knows about the DOM, the AudioContext, and the order things happen in.
 */

/**
 * Minimum dead air after a pitch before the next windup — on top of waiting for
 * the booth to finish. Radio baseball needs room for the count, the chess, and
 * a breath; 1.5 s was a video-game cadence.
 */
const BETWEEN_PITCHES_SEC = 5.2;
/** Extra hold after a half-inning break call before play resumes. */
const INNING_BREAK_SEC = 2.8;
/** Padding after the commentary queue goes idle so the last syllable clears. */
const BOOTH_CLEAR_PAD_MS = 400;

let renderGameState = (): string => JSON.stringify({
  mode: "menu",
  instructions: "Choose a team and activate Play Ball. Headphones recommended.",
  controls: { primary: "Tap or Space", fullscreen: "F" },
});

window.render_game_to_text = (): string => renderGameState();

window.addEventListener("keydown", (event) => {
  if (event.key.toLowerCase() !== "f" || event.altKey || event.ctrlKey || event.metaKey) return;
  const target = event.target;
  if (target instanceof HTMLInputElement || target instanceof HTMLSelectElement || target instanceof HTMLTextAreaElement) return;
  event.preventDefault();
  if (document.fullscreenElement) void document.exitFullscreen();
  else void document.documentElement.requestFullscreen();
});

function requireElement<T extends HTMLElement>(id: string): T {
  const element = document.getElementById(id);
  if (!element) throw new Error(`Missing element #${id}`);
  return element as T;
}

const gate = requireElement("gate");
const booth = requireElement("booth");
const playBallButton = requireElement<HTMLButtonElement>("play-ball");
const playerSideSelect = requireElement<HTMLSelectElement>("player-side");
const sessionModeSelect = requireElement<HTMLSelectElement>("session-mode");
const sessionLengthSelect = requireElement<HTMLSelectElement>("session-length");
const roleLockSelect = requireElement<HTMLSelectElement>("role-lock");
const sessionLengthLabel = requireElement("session-length-label");
const roleLockLabel = requireElement("role-lock-label");
let sessionOptions: SessionOptions = loadSessionOptions();
let prefs: Prefs = loadPrefs();

applyBroadcastTheme(readArcadeBroadcastTheme() ?? prefs.broadcastTheme);

{
  const saved = loadPlayerSide();
  playerSideSelect.value = saved;
  sessionModeSelect.value = sessionOptions.mode;
  sessionLengthSelect.value = String(sessionOptions.length);
  roleLockSelect.value = sessionOptions.roleLock;
}

function syncSessionGate(): void {
  const mode = isSessionMode(sessionModeSelect.value) ? sessionModeSelect.value : "exhibition";
  const length = Number(sessionLengthSelect.value);
  const roleLock = isRoleLock(roleLockSelect.value) ? roleLockSelect.value : "both";
  sessionOptions = {
    mode,
    length: isSessionLength(length) ? length : 9,
    roleLock,
  };
  const practice = mode === "practice";
  sessionLengthLabel.hidden = practice;
  roleLockLabel.hidden = practice;
  saveSessionOptions(sessionOptions);
}

sessionModeSelect.addEventListener("change", syncSessionGate);
sessionLengthSelect.addEventListener("change", syncSessionGate);
roleLockSelect.addEventListener("change", syncSessionGate);
syncSessionGate();

playBallButton.addEventListener("click", () => {
  playBallButton.disabled = true;
  void start().catch((error: unknown) => {
    playBallButton.disabled = false;
    // eslint-disable-next-line no-console
    console.error("Failed to start the broadcast", error);
  });
});

async function start(): Promise<void> {
  // AudioContext construction and resume both live behind the user gesture.
  const engine = new AudioEngine();
  await engine.resume();
  // SpeechSynthesis also needs the gesture, or the first call is silently dropped.
  warmUpSpeech();
  // Decode bat/glove/crowd clips before the bed starts so we don't flash static.
  await engine.samples.load(engine.ctx);

  const sideValue = playerSideSelect.value;
  const playerSide: PlayerSide = isPlayerSide(sideValue) ? sideValue : "home";
  savePlayerSide(playerSide);
  const playerTeam = teamForSide(playerSide);

  gate.hidden = true;
  booth.hidden = false;
  // Collapse only the optional visual board on small screens — feed/score stay up.
  if (window.matchMedia("(max-width: 900px)").matches) {
    requireElement<HTMLDetailsElement>("gameday-fold").open = false;
  }

  const rng = Math.random;

  const radioLog = new RadioLog(requireElement<HTMLOListElement>("radio-log"));
  const liveScore = new LiveScore(requireElement("live-score"));
  const gameday = new GamedayBoard(requireElement("gameday"));
  gameday.setPlayerTeam(playerTeam.shortName);
  const liveStats = new LiveStats(HOME_TEAM, AWAY_TEAM);
  const input = new SwingInput();
  const calibration = new Calibration(engine, input, {
    onStatus: (text) => {
      requireElement("calibration-status").textContent = text;
    },
  });
  const readout = new SwingReadout(requireElement("swing-readout"));
  const difficultyAnnounce = requireElement("difficulty-announce");
  const spaceHint = requireElement("space-hint");
  const pitchCall = new PitchCallPanel(requireElement("pitch-call"));

  function applyAnnounceMode(): void {
    // Booth TTS carries lines by default; live log would double-speak with SR.
    radioLog.setLive(prefs.announceMode === "screen-reader" || prefs.announceMode === "both");
  }
  applyAnnounceMode();

  /** Coach tips: always update the status region; TTS only when booth modes allow. */
  function coachSpeak(
    text: string,
    options: { energy?: number; speaker?: "announcer" | "color" | "umpire"; interrupt?: boolean } = {},
  ): void {
    difficultyAnnounce.textContent = text;
    if (prefs.coachVerbosity === "off") return;
    if (prefs.announceMode === "screen-reader") return;
    // Don't let OS coach TTS steal the booth identity when directed samples are on.
    if (prefs.boothVoice === "sampled") return;
    const request: Parameters<typeof speakNow>[0] = {
      text,
      speaker: options.speaker ?? "announcer",
      energy: options.energy ?? 0.35,
    };
    if (options.interrupt !== undefined) request.interrupt = options.interrupt;
    speakNow(request);
  }

  // Booth words: sampled directed clips when preferred + available, else Web Speech.
  // Delivery calls stay silent so they do not talk over the windup pulse.
  const speechBackend = new SpeechVoiceBackend(engine, radioLog, () => prefs.announceMode);
  const sampledBackend = new SampledVoiceBackend({
    engine,
    log: radioLog,
    fallback: speechBackend,
    getAnnounceMode: () => prefs.announceMode,
  });
  await sampledBackend.load();

  const backend: VoiceBackend = {
    estimateDuration: (phrase) => activeBoothBackend().estimateDuration(phrase),
    speak: (phrase, at) => activeBoothBackend().speak(phrase, at),
  };

  function activeBoothBackend(): VoiceBackend {
    return prefs.boothVoice === "sampled" ? sampledBackend : speechBackend;
  }

  const queue = new CommentaryQueue(backend, () => engine.currentTime);
  const crowd = new CrowdBed(engine);
  /** Vendor shouts fire between pitches when the booth is quiet — atmosphere, not dialogue. */
  let pitchesSinceVendor = 0;
  const state = new GameState(HOME_TEAM, AWAY_TEAM, rng, { regulationInnings: sessionOptions.length });
  const selector = new PitchSelector(rng);

  let difficulty: DifficultyConfig = getDifficulty(loadDifficultyId());
  selector.setDifficulty(difficulty);
  readout.setWindows(difficulty.perfectWindowMs, difficulty.contactWindowMs);

  const timingCoach = new TimingCoach(requireElement("timing-coach"), engine, () => difficulty);
  const timingCue = requireElement("timing-cue");
  const calGateHint = requireElement("cal-gate-hint");
  const skipCalibrationButton = requireElement<HTMLButtonElement>("skip-cal");
  let calibrationGateOpen = !calibration.isCalibrated && !prefs.calibrationSkipped;

  /** Rookie-plus assists and wider windows when playing through a screen reader. */
  function effectiveDifficulty(): DifficultyConfig {
    const base = difficulty;
    if (prefs.announceMode !== "screen-reader") return base;
    return {
      ...base,
      perfectWindowMs: Math.round(base.perfectWindowMs * 1.6),
      contactWindowMs: Math.round(base.contactWindowMs * 1.6),
      countableBeats: true,
      plateTick: true,
      spokenSwing: true,
    };
  }

  function assistWindows(base: { perfectWindowMs: number; contactWindowMs: number }): {
    perfectWindowMs: number;
    contactWindowMs: number;
  } {
    if (prefs.announceMode !== "screen-reader") return base;
    return {
      perfectWindowMs: Math.round(base.perfectWindowMs * 1.6),
      contactWindowMs: Math.round(base.contactWindowMs * 1.6),
    };
  }

  const sequencer = new PitchSequencer({
    engine,
    input,
    getCalibrationMs: () => calibration.offsetMs,
    getDifficulty: () => effectiveDifficulty(),
    rng,
    onTimingCue: (text) => {
      // Clear-then-set so assertive SR users hear repeats on consecutive pitches.
      timingCue.textContent = "";
      requestAnimationFrame(() => {
        timingCue.textContent = text === "swing" ? "Swing!" : "Release!";
      });
    },
    shouldSpeakTimingCue: () => prefs.announceMode !== "screen-reader",
  });

  let lastRoleBatting: boolean | null = null;

  // --- Crowd excitement: driven by game leverage, not a slider -------------
  // The slider still exists as a small manual trim (-2..+2) on top of the
  // computed value, so the player retains a control, but the primary driver is
  // the situation on the field: score margin, runners, outs, inning.
  const crowdSlider = requireElement<HTMLInputElement>("crowd-level");
  const crowdOut = requireElement<HTMLOutputElement>("crowd-level-out");
  let lastLeverage = 0;

  function currentExcitement(snapshot: GameSnapshot): ExcitementLevel {
    const leverage = computeLeverage(snapshot);
    lastLeverage = leverage;
    const bias = Number(crowdSlider.value);
    return clampLevel(excitementForLeverage(leverage) + bias);
  }

  crowdSlider.addEventListener("input", () => {
    crowdOut.textContent = crowdSlider.value;
    crowd.setExcitement(currentExcitement(state.snapshot()), 0.8);
  });

  const diagnostics = new Diagnostics(requireElement("diagnostics"), engine, () => calibration.offsetMs, () => ({
    leverage: lastLeverage,
    excitement: crowd.excitement,
  }));
  const timingDeltas: number[] = [];
  function recordTiming(deltaMs: number): void {
    timingDeltas.push(deltaMs);
    if (timingDeltas.length > 60) timingDeltas.shift();
    diagnostics.recordSwing(deltaMs);
  }
  const actionPad = new ActionPad(
    requireElement<HTMLButtonElement>("action-fab"),
    requireElement<HTMLButtonElement>("timing-action"),
    input,
  );
  const endGameCard = new EndGameCard(requireElement("end-card"));

  crowd.start();
  crowd.attachSamples();
  diagnostics.start();

  function paintBoard(): void {
    const snapshot = state.snapshot();
    gameday.render(liveStats.snapshot(snapshot));
    liveScore.render(snapshot);
  }

  paintBoard();

  // Pre-game. The crowd bed is up so you know audio is alive, but no pitches are
  // thrown until you say so — calibration has to be reachable *before* the first
  // pitch, not squeezed in between two of them.
  readout.showMessage(
    calibration.offsetMs === 0
      ? "Calibrate latency first, then start when ready."
      : `Calibrated ${calibration.offsetMs >= 0 ? "+" : ""}${calibration.offsetMs.toFixed(0)} ms. Start when ready.`,
    calibration.offsetMs === 0 ? "warn" : null,
  );

  // --- Mixer (non-excitement controls) --------------------------------------
  const radioToggle = requireElement<HTMLInputElement>("radio-filter");
  radioToggle.checked = prefs.radioFilterDefault;
  engine.setRadioFilter(radioToggle.checked);
  radioToggle.addEventListener("change", () => {
    engine.setRadioFilter(radioToggle.checked);
    prefs = patchPrefs({ radioFilterDefault: radioToggle.checked });
  });

  const difficultySelect = requireElement<HTMLSelectElement>("difficulty");
  for (const id of DIFFICULTY_ORDER) {
    const option = difficultySelect.querySelector(`option[value="${id}"]`);
    if (option instanceof HTMLOptionElement && id === difficulty.id) option.selected = true;
  }

  function applyDifficulty(id: DifficultyId, announce: boolean): void {
    difficulty = getDifficulty(id);
    saveDifficultyId(id);
    selector.setDifficulty(difficulty);
    readout.setWindows(difficulty.perfectWindowMs, difficulty.contactWindowMs);
    timingCoach.setDifficulty(() => difficulty);
    if (announce) coachSpeak(difficulty.announce);
  }

  applyDifficulty(difficulty.id, false);

  difficultySelect.addEventListener("change", () => {
    const value = difficultySelect.value;
    if (!isDifficultyId(value)) return;
    applyDifficulty(value, true);
  });

  const masterSlider = requireElement<HTMLInputElement>("master-gain");
  const masterOut = requireElement<HTMLOutputElement>("master-gain-out");
  masterSlider.addEventListener("input", () => {
    engine.setMasterLevel(Number(masterSlider.value) / 100);
    masterOut.textContent = masterSlider.value;
  });

  const bindBusLevel = (
    inputId: string,
    outputId: string,
    bus: "field" | "crowd" | "announcer",
    floor = 0,
  ): void => {
    const slider = requireElement<HTMLInputElement>(inputId);
    const output = requireElement<HTMLOutputElement>(outputId);
    const apply = (): void => {
      const level = Math.max(floor, Number(slider.value) / 100);
      engine.bus(bus).setLevel(level);
      if (bus === "announcer") engine.bus("color").setLevel(level * 0.85);
      output.textContent = String(Math.round(level * 100));
    };
    slider.addEventListener("input", apply);
    apply();
  };
  bindBusLevel("field-gain", "field-gain-out", "field", 0.4);
  bindBusLevel("crowd-bus-gain", "crowd-bus-gain-out", "crowd");
  bindBusLevel("booth-gain", "booth-gain-out", "announcer");

  const speechRate = requireElement<HTMLInputElement>("speech-rate");
  const speechRateOut = requireElement<HTMLOutputElement>("speech-rate-out");
  speechRate.value = String(Math.round(prefs.speechRate * 100));
  const applySpeechRate = (): void => {
    const value = Number(speechRate.value) / 100;
    setSpeechRateMultiplier(value);
    speechRateOut.textContent = `${Math.round(value * 100)}%`;
  };
  speechRate.addEventListener("input", () => {
    applySpeechRate();
    prefs = patchPrefs({ speechRate: Number(speechRate.value) / 100 });
  });
  applySpeechRate();

  const coachVerbosity = requireElement<HTMLSelectElement>("coach-verbosity");
  coachVerbosity.value = prefs.coachVerbosity;
  coachVerbosity.addEventListener("change", () => {
    if (coachVerbosity.value === "full" || coachVerbosity.value === "short" || coachVerbosity.value === "off") {
      prefs = patchPrefs({ coachVerbosity: coachVerbosity.value });
    }
  });

  const announceModeSelect = requireElement<HTMLSelectElement>("announce-mode");
  announceModeSelect.value = prefs.announceMode;
  announceModeSelect.addEventListener("change", () => {
    if (!isAnnounceMode(announceModeSelect.value)) return;
    prefs = patchPrefs({ announceMode: announceModeSelect.value });
    applyAnnounceMode();
    coachSpeak(
      prefs.announceMode === "screen-reader"
        ? "Announce mode: screen reader play-by-play. Timing windows are wider, and Swing stays in Controls."
        : prefs.announceMode === "both"
          ? "Announce mode: booth speech and screen reader log."
          : "Announce mode: booth speech.",
    );
    const eff = effectiveDifficulty();
    readout.setWindows(eff.perfectWindowMs, eff.contactWindowMs);
  });

  const boothVoiceSelect = requireElement<HTMLSelectElement>("booth-voice");
  boothVoiceSelect.value = prefs.boothVoice;
  boothVoiceSelect.addEventListener("change", () => {
    if (!isBoothVoice(boothVoiceSelect.value)) return;
    prefs = patchPrefs({ boothVoice: boothVoiceSelect.value });
    if (prefs.boothVoice === "sampled") void sampledBackend.load();
    coachSpeak(
      prefs.boothVoice === "sampled"
        ? "Booth voice: directed samples when available, speech fallback otherwise."
        : "Booth voice: system speech.",
    );
  });

  // --- Transport -----------------------------------------------------------
  /**
   * `loopActive` is the re-entry guard, and it is load-bearing. Three things can
   * ask the game to stop and start again — the pause button, calibration, and the
   * timing harness — and two overlapping loops would fight over the sequencer,
   * which rejects a second pitch while one is live. Requesting a stop is therefore
   * always asynchronous: set the flag, then wait for the loop to actually exit.
   */
  let loopActive = false;
  let stopRequested = false;
  /** Set the instant a play ends the game. Distinct from `stopRequested` because
   *  the transport button needs to know *why* it stopped: "Resume" vs "New Game". */
  let gameOver = false;
  let sessionStartedAt = performance.now();

  renderGameState = (): string => {
    const snapshot = state.snapshot();
    return JSON.stringify({
      mode: gameOver ? "game-over" : loopActive ? "playing" : "ready",
      coordinateSystem: "Audio-first game; pitch location is described as horizontal stereo pan and vertical brightness.",
      playerSide,
      playerRole: isPlayerBatting(snapshot, playerSide) ? "batting" : "pitching",
      inning: snapshot.inning,
      half: snapshot.half,
      count: { balls: snapshot.balls, strikes: snapshot.strikes, outs: snapshot.outs },
      score: snapshot.score,
      bases: snapshot.bases,
      batter: snapshot.batter,
      pitcher: snapshot.pitcher,
      difficulty: difficulty.id,
      controls: { primary: "Tap or Space", transport: "next-pitch button", fullscreen: "F" },
    });
  };

  const transport = requireElement<HTMLButtonElement>("next-pitch");

  function syncRoleChrome(
    snapshot: GameSnapshot,
    options: { setTransport?: boolean; announceRoleChange?: boolean } = {},
  ): void {
    const batting = isPlayerBatting(snapshot, playerSide);
    timingCoach.setRole(batting ? "bat" : "pitch");
    actionPad.setRole(batting ? "bat" : "pitch");
    const roleAllowsPad =
      !gameOver &&
      !calibrationGateOpen &&
      sessionOptions.mode !== "practice" &&
      (sessionOptions.roleLock === "both" ||
        (sessionOptions.roleLock === "bat" && batting) ||
        (sessionOptions.roleLock === "pitch" && !batting));
    actionPad.setEnabled(roleAllowsPad);
    spaceHint.textContent = batting
      ? "During the pitch: activate Swing (or press Space) on beat five. Count four, swing on five."
      : "During the windup: activate Release (or press Space) on beat four, then the pitch flies.";
    pitchCall.setActive(!batting && sessionOptions.roleLock !== "bat");
    if (options.setTransport && !gameOver) {
      transport.textContent = batting ? "Start at-bat" : "Ready to pitch";
    }
    if (options.announceRoleChange !== false && lastRoleBatting !== null && lastRoleBatting !== batting) {
      coachSpeak(roleAnnounce(batting), { energy: 0.4 });
    }
    lastRoleBatting = batting;
  }

  function applyCalibrationGate(): void {
    skipCalibrationButton.hidden = !calibrationGateOpen;
    calGateHint.hidden = !calibrationGateOpen;
    transport.disabled = calibrationGateOpen;
    if (calibrationGateOpen) {
      skipCalibrationButton.classList.add("primary");
      skipCalibrationButton.classList.remove("secondary");
      readout.showMessage("Calibrate first, or choose Skip calibration — start playing.", "warn");
    } else {
      skipCalibrationButton.classList.remove("primary");
      skipCalibrationButton.classList.add("secondary");
    }
  }

  const sideLine = announcePlayerSide(playerSide);
  coachSpeak(`${sideLine} ${difficulty.announce}`, { energy: 0.4 });
  applyCalibrationGate();
  syncRoleChrome(state.snapshot(), { setTransport: true, announceRoleChange: false });

  // Land keyboard/SR focus in the control rail after leaving the gate.
  queueMicrotask(() => {
    const cal = requireElement<HTMLButtonElement>("calibrate");
    if (calibrationGateOpen) skipCalibrationButton.focus();
    else if (!calibration.isCalibrated) cal.focus();
    else transport.focus();
  });

  const calibrateButton = requireElement<HTMLButtonElement>("calibrate");
  const calibrationTapZone = requireElement("cal-tap-zone");

  skipCalibrationButton.addEventListener("click", () => {
    prefs = patchPrefs({ calibrationSkipped: true });
    calibrationGateOpen = false;
    applyCalibrationGate();
    syncRoleChrome(state.snapshot());
    readout.showMessage("Calibration skipped. Start at-bat is ready.", "warn");
    coachSpeak("Calibration skipped. Start at-bat is ready.", { energy: 0.35 });
    queueMicrotask(() => transport.focus());
    if (sessionOptions.mode === "practice" && !loopActive) void runLoop();
  });

  /**
   * Stop now, not at the end of the current pitch.
   *
   * Cancelling the live pitch cuts the ball out of the air and rejects the
   * sequencer promise, which drops the loop out immediately. Waiting politely for
   * the pitch to reach the plate meant up to two seconds of nothing happening
   * after you clicked Pause, which reads as a dead button.
   */
  async function stopLoop(): Promise<void> {
    stopRequested = true;
    pitchCall.cancelWait();
    sequencer.cancel();
    await waitForIdle(() => !loopActive);
    // Whatever the booth was still going to say about a pitch we just abandoned
    // is no longer worth hearing.
    queue.clear();
    cancelAllSpeech();
    syncRoleChrome(state.snapshot(), { setTransport: true });
  }

  function resetGame(): void {
    state.reset();
    liveStats.reset();
    gameOver = false;
    sessionStartedAt = performance.now();
    stopRequested = false;
    lastRoleBatting = null;
    radioLog.clear();
    diagnostics.reset();
    timingDeltas.length = 0;
    queue.clear();
    cancelAllSpeech();
    paintBoard();
    crowd.setExcitement(currentExcitement(state.snapshot()), 1.5);
    readout.showMessage("New game. Start when ready.", null);
    transport.disabled = false;
    syncRoleChrome(state.snapshot(), { setTransport: true, announceRoleChange: false });
    endGameCard.hide();
  }

  endGameCard.onAction((action) => {
    if (action === "new") {
      resetGame();
      return;
    }
    if (action === "difficulty") {
      endGameCard.hide();
      difficultySelect.focus();
      return;
    }
    const feedback = document.getElementById("cade-feedback-open") ??
      document.querySelector<HTMLElement>("[data-feedback-open], #feedback-open");
    if (feedback instanceof HTMLElement) feedback.click();
    else window.focus();
  });

  requireElement<HTMLButtonElement>("announce-situation").addEventListener("click", () => {
    const snapshot = state.snapshot();
    const line = `${formatScore(snapshot.score, snapshot.homeTeam, snapshot.awayTeam)}. ${snapshot.half} of the ${snapshot.inning}${ordinal(snapshot.inning)}. ${snapshot.outs} out${snapshot.outs === 1 ? "" : "s"}, count ${formatCount(snapshot.balls, snapshot.strikes)}. ${formatBases(snapshot.bases)}.`;
    queue.say({ id: "situation.manual", text: line, speaker: "announcer", energy: 0.3 }, {
      notBefore: engine.currentTime,
      priority: PRIORITY.playByPlay,
    });
  });

  transport.addEventListener("click", () => {
    // Drop focus, or the button stays keyboard-active and steals the spacebar's
    // visual affordance from the swing.
    transport.blur();
    if (gameOver) {
      resetGame();
      return;
    }
    if (loopActive) {
      void stopLoop();
      return;
    }
    if (calibrationGateOpen) {
      readout.showMessage("Calibrate first, or choose Skip calibration — start playing.", "warn");
      skipCalibrationButton.focus();
      return;
    }
    stopRequested = false;
    void runLoop();
  });

  calibrateButton.addEventListener("click", () => {
    if (calibration.isRunning) return;
    calibrateButton.blur();
    calibrateButton.disabled = true;
    const wasRunning = loopActive;
    void (async () => {
      // Calibration owns the spacebar and the field bus, so the game has to be
      // fully stopped first — not merely asked to stop.
      await stopLoop();
      readout.showMessage("Tap or press SPACE on each click...", "warn");
      calibrationTapZone.hidden = false;
      requireElement<HTMLButtonElement>("cal-tap-target").focus();
      await calibration.run();
      calibrationTapZone.hidden = true;
      diagnostics.reset();
      calibrateButton.disabled = false;
      stopRequested = false;

      const offset = calibration.offsetMs;
      readout.showMessage(
        offset === 0
          ? "Calibration didn't register enough taps — try again."
          : `Calibrated ${offset >= 0 ? "+" : ""}${offset.toFixed(0)} ms.`,
        offset === 0 ? "warn" : null,
      );
      if (calibration.isCalibrated) {
        calibrationGateOpen = false;
        applyCalibrationGate();
        syncRoleChrome(state.snapshot());
        coachSpeak("Calibration complete. Start at-bat is ready.", { energy: 0.35 });
        queueMicrotask(() => transport.focus());
        if (sessionOptions.mode === "practice" && !wasRunning) void runLoop();
      }

      // Resume only if we interrupted a live at-bat, and the game isn't over.
      if (wasRunning && !gameOver) void runLoop();
    })();
  });

  installTimingHarness({
    engine,
    input,
    sequencer,
    getCalibrationMs: () => calibration.offsetMs,
    pause: stopLoop,
  });
  if (sessionOptions.mode === "practice" && !calibrationGateOpen) void runLoop();

  // --- The loop ------------------------------------------------------------
  async function runLoop(): Promise<void> {
    if (sessionOptions.mode === "practice") {
      await runPracticeLoop();
      return;
    }
    if (loopActive || gameOver) return;
    loopActive = true;
    transport.textContent = "Pause";
    transport.disabled = false;
    try {
      while (!stopRequested) {
        try {
          const gap = await throwOne();
          if (stopRequested || gameOver) break;
          // Hold for the longer of the minimum radio gap and "booth is done talking".
          await waitForBroadcastGap(gap);
        } catch {
          // A cancelled pitch (calibration, teardown) simply ends the loop.
          break;
        }
      }
    } finally {
      loopActive = false;
      pitchCall.cancelWait();
      syncRoleChrome(state.snapshot(), { setTransport: false });
      transport.textContent = gameOver ? "New Game" : "Resume";
      transport.disabled = false;
      if (!gameOver) crowd.setExcitement(currentExcitement(state.snapshot()), 1.5);
    }
  }

  async function runPracticeLoop(): Promise<void> {
    if (loopActive || calibrationGateOpen) return;
    loopActive = true;
    transport.textContent = "Pause";
    transport.disabled = false;
    actionPad.setEnabled(true);
    try {
      while (!stopRequested) {
        const gap = await throwPracticePitch();
        if (stopRequested) break;
        await waitForBroadcastGap(gap);
      }
    } catch {
      // Pause and calibration intentionally cancel the live practice pitch.
    } finally {
      loopActive = false;
      input.disarm();
      actionPad.setEnabled(false);
      transport.textContent = "Resume";
      transport.disabled = false;
    }
  }

  async function throwPracticePitch(): Promise<number> {
    selector.setPitcher(pitcherRatingsOf(state.currentPitcher()));
    selector.setDifficulty(getDifficulty("rookie"));
    const call = selector.select(0, 0);
    const pressesBefore = input.ignoredPresses;
    const result = await sequencer.throwPitch(call.profile, call.location, {
      onScheduled: (timeline) => timingCoach.arm(timeline),
      windows: {
        perfectWindowMs: difficulty.perfectWindowMs,
        contactWindowMs: difficulty.contactWindowMs,
      },
    });
    timingCoach.clear();
    if (result.judgment.swung) {
      recordTiming(result.judgment.deltaMs);
      readout.showSwing(result.judgment.deltaMs, result.judgment.contact);
    } else {
      readout.showTake(input.ignoredPresses - pressesBefore);
    }
    if (prefs.coachVerbosity !== "off") {
      coachSpeak(
        prefs.coachVerbosity === "short" ? describeLocation(call.location) : `Fastball ${describeLocation(call.location)}.`,
        { speaker: "color", energy: 0.3, interrupt: false },
      );
    }
    return BETWEEN_PITCHES_SEC;
  }

  /**
   * Wait until the booth has finished its between-pitch fill *and* at least
   * `minSec` has elapsed since the pitch resolved. Polls so Pause/calibration
   * can break out without sitting on a single long sleep.
   */
  async function waitForBroadcastGap(minSec: number): Promise<void> {
    const earliest = performance.now() + minSec * 1000;
    while (!stopRequested) {
      const boothRemainingMs = Math.max(0, (queue.busyUntil - engine.currentTime) * 1000);
      const minRemainingMs = earliest - performance.now();
      if (boothRemainingMs <= 40 && minRemainingMs <= 0) break;
      const wait = Math.min(120, Math.max(40, boothRemainingMs, minRemainingMs));
      await sleep(wait);
    }
    if (!stopRequested) await sleep(BOOTH_CLEAR_PAD_MS);
  }

  /** @returns Minimum seconds to hold before the next pitch (inning breaks get longer). */
  async function throwOne(): Promise<number> {
    const before = state.snapshot();
    const leverage = computeLeverage(before);
    const playerBatting = isPlayerBatting(before, playerSide);
    syncRoleChrome(before, { setTransport: false });
    let nextGap = BETWEEN_PITCHES_SEC;

    crowd.setExcitement(currentExcitement(before), 0.8);

    // A fresh plate appearance is exactly the pitches where the count reads 0-0 —
    // `GameState` resets the count at that boundary and nowhere else, so it's a
    // reliable signal with no extra bookkeeping needed here.
    const isNewBatter = before.balls === 0 && before.strikes === 0;
    if (isNewBatter) {
      const situation = buildSituationLine(before, leverage, before.homeTeam, before.awayTeam, rng);
      if (situation) {
        const sitEnd = queue.say(situation, {
          notBefore: engine.currentTime + 0.12,
          priority: PRIORITY.playByPlay,
        });
        // Let the batter intro land before the windup pulse — radio does the
        // same, then the pitcher comes set.
        const introMs = Math.min(9000, Math.max(0, (sitEnd - engine.currentTime) * 1000 - 150));
        await sleep(introMs);
        if (stopRequested) return nextGap;
      }
    }

    const batterPlayer = state.currentBatter();
    const pitcherPlayer = state.currentPitcher();
    const batterRatings = batterRatingsOf(batterPlayer);
    const pitcherRatings = pitcherRatingsOf(pitcherPlayer);
    selector.setPitcher(pitcherRatings);

    let call: PitchCall;
    let judgment: SwingJudgment;
    let contactTime: number;
    let followUpTime: number;
    let profileForStats: PitchCall["profile"];
    let locationForStats: PitchCall["location"];

    const humanBatting = playerBatting && sessionOptions.roleLock !== "pitch";
    const humanPitching = !playerBatting && sessionOptions.roleLock !== "bat";

    if (humanBatting) {
      call = selector.select(before.balls, before.strikes);

      // Log-only delivery cue. Preempts leftover colour so it can't spill into the windup.
      queue.say(buildDeliveryCall(before.pitcher, rng), {
        notBefore: engine.currentTime + 0.05,
        priority: PRIORITY.playByPlay,
        preempt: true,
      });

      const batterWindows = assistWindows(
        windowsForBatter(
          {
            perfectWindowMs: difficulty.perfectWindowMs,
            contactWindowMs: difficulty.contactWindowMs,
          },
          batterRatings,
        ),
      );

      const pressesBefore = input.ignoredPresses;
      let result: PitchResult;
      try {
        result = await sequencer.throwPitch(call.profile, call.location, {
          onScheduled: (timeline) => timingCoach.arm(timeline),
          windows: batterWindows,
        });
      } catch (error) {
        timingCoach.clear();
        throw error;
      }
      timingCoach.clear();

      if (result.judgment.swung) {
        recordTiming(result.judgment.deltaMs);
        readout.showSwing(result.judgment.deltaMs, result.judgment.contact);
      } else {
        readout.showTake(input.ignoredPresses - pressesBefore);
      }

      judgment = result.judgment;
      contactTime = result.contactTime;
      followUpTime = result.followUpTime;
      profileForStats = call.profile;
      locationForStats = call.location;
    } else {
      if (humanPitching) {
        pitchCall.setActive(true);
        try {
          call = await pitchCall.waitForCall();
        } catch (error) {
          throw error;
        }
        if (stopRequested) return nextGap;

        // Human call pad chooses type/location; scale velo/flight to the starter.
        call = {
          profile: profileForPitcher(call.profile.type, pitcherRatings),
          location: call.location,
        };

        const callLine = pitchCall.describeCurrent();
        if (prefs.coachVerbosity !== "off") {
          coachSpeak(callLine, { energy: 0.35 });
        } else {
          difficultyAnnounce.textContent = callLine;
        }
      } else {
        // Role lock gives this half to the AI. `throwPitchAsPitcher` auto-releases
        // when no input arrives, so this preserves the pitcher-side audio path.
        call = selector.select(before.balls, before.strikes);
      }

      queue.say(buildDeliveryCall(before.pitcher, rng), {
        notBefore: engine.currentTime + 0.05,
        priority: PRIORITY.playByPlay,
        preempt: true,
      });

      let pitcherResult: PitcherResult;
      try {
        pitcherResult = await sequencer.throwPitchAsPitcher(call.profile, call.location, {
          onScheduled: (timeline) => timingCoach.arm(timeline),
        });
      } catch (error) {
        timingCoach.clear();
        throw error;
      }
      timingCoach.clear();

      readout.showRelease(pitcherResult.release.deltaMs, pitcherResult.release.autoReleased);
      recordTiming(pitcherResult.release.deltaMs);

      // AI uses its own windows (see aiBatterWindows) — not human Rookie assists.
      judgment = decideBatterSwing({
        balls: before.balls,
        strikes: before.strikes,
        profile: pitcherResult.finalProfile,
        location: pitcherResult.finalLocation,
        perceivedPlateMs: pitcherResult.perceivedPlateMs,
        difficulty,
        batter: batterRatings,
        pitcher: pitcherRatings,
        rng,
      });

      playPitchAftermath(
        engine,
        judgment,
        pitcherResult.contactTime,
        pitcherResult.finalProfile.velocityMph,
        pitcherResult.cutFlight,
      );

      contactTime = pitcherResult.contactTime;
      followUpTime = pitcherResult.followUpTime;
      profileForStats = pitcherResult.finalProfile;
      locationForStats = pitcherResult.finalLocation;
      call = { profile: pitcherResult.finalProfile, location: pitcherResult.finalLocation };
    }

    const play = resolvePlay(judgment, rng, batterRatings);
    const report = state.applyPlay(play);
    const after = state.snapshot();

    if (difficulty.id === "rookie" && prefs.coachVerbosity !== "off") {
      coachSpeak(
        prefs.coachVerbosity === "short"
          ? describeLocation(locationForStats)
          : `That pitch was ${describeLocation(locationForStats)}.`,
        { speaker: "color", energy: 0.3, interrupt: false },
      );
    }

    liveStats.recordPitch({
      before,
      after,
      report,
      play,
      profile: profileForStats,
      location: locationForStats,
      inZone: isInStrikeZone(locationForStats),
    });
    paintBoard();
    if (report.inningEnded && !report.gameEnded) {
      syncRoleChrome(after, { setTransport: false });
    }

    // Umpire first — quiet field bark for place, spoken words through the queue.
    const ump = umpireCallFor(play, report.outcome);
    let voiceFloor = followUpTime;
    if (ump) {
      playUmpireCall(engine, ump, followUpTime);
      const umpPhrase: Phrase = {
        id: `umpire.${ump}`,
        text: UMPIRE_WORDS[ump],
        speaker: "umpire",
        energy: ump === "strike-three" ? 0.95 : 0.7,
      };
      // Same priority as play-by-play so the result call's cancelBelow doesn't
      // wipe an umpire line that hasn't started yet but is scheduled first.
      voiceFloor = queue.say(umpPhrase, {
        notBefore: followUpTime,
        priority: PRIORITY.playByPlay,
      });
      voiceFloor = Math.max(voiceFloor, followUpTime + umpireCallDuration(ump)) + 0.12;
    }

    const playExcitement = excitementFor(play);
    if (report.walkOff) {
      crowd.swell(contactTime, 5, 3.2);
    } else if (playExcitement >= 4) {
      crowd.swell(contactTime, playExcitement, play === "home-run" ? 2.6 : 1.2);
    } else if (report.outcome.kind === "strikeout") {
      crowd.swell(followUpTime, 4, 1.0);
    }

    const narration: NarrationContext = {
      pitcher: before.pitcher,
      batter: before.batter,
      batterHand: batterHandForAb(before.batter, before.pitcher),
      homeTeamName: before.homeTeam,
      awayTeamName: before.awayTeam,
      profile: call.profile,
      location: call.location,
      judgment,
      result: play,
      outcome: report.outcome,
      report,
      after,
      countBefore: { balls: before.balls, strikes: before.strikes },
      countAfter: countAfterFor(before, after, report.outcome),
      spray: clamp(-judgment.deltaMs / 70, -1, 1),
      leverage,
      rng,
    };

    let voiceEnd = queue.say(buildResultCall(narration), {
      notBefore: voiceFloor,
      priority: PRIORITY.playByPlay,
    });

    const colorLine = buildColorLine(narration);
    if (colorLine) {
      voiceEnd = queue.say(colorLine, { notBefore: voiceEnd + 0.3, priority: PRIORITY.color });
    }

    // Bridge fill: count, situation, chess — the sound of baseball on the radio.
    if (!report.gameEnded) {
      for (const bridge of buildBetweenPitchFill(narration)) {
        const priority = bridge.speaker === "color" ? PRIORITY.color : PRIORITY.playByPlay;
        voiceEnd = queue.say(bridge, { notBefore: voiceEnd + 0.35, priority });
      }
    }

    // Between-play "run scores" flourish. Fires on any play that plated a run —
    // hit, sac fly, productive out, or a bases-loaded walk — not just hits.
    if (report.runsScored > 0 && !report.gameEnded) {
      crowd.organStab(voiceEnd + 0.3);
    }

    if (report.gameEnded) {
      gameOver = true;
      stopRequested = true;
      const playerRuns = after.score[playerSide];
      const opponentRuns = after.score[playerSide === "home" ? "away" : "home"];
      window.dispatchEvent(new CustomEvent("baseball-radio-game-over", {
        detail: {
          playerRuns,
          opponentRuns,
          innings: after.inning,
          won: playerRuns > opponentRuns,
          durationMs: Math.max(0, Math.round(performance.now() - sessionStartedAt)),
        },
      }));
      const meanTiming = timingDeltas.length === 0
        ? "No timed swings recorded."
        : `Timing: ${timingDeltas.length} swings, ${Math.round(timingDeltas.reduce((sum, value) => sum + value, 0) / timingDeltas.length)} ms average.`;
      endGameCard.show({
        won: playerRuns > opponentRuns,
        playerRuns,
        opponentRuns,
        innings: after.inning,
        timingSummary: meanTiming,
        modeLabel: describeSession(sessionOptions),
      });
      const gameOverCall = buildGameOverCall(report, after, before.batter, before.homeTeam, before.awayTeam, rng);
      queue.say(gameOverCall, { notBefore: voiceEnd + 0.4, priority: PRIORITY.playByPlay });
      crowd.organStab(voiceEnd + 1.6, 220);
    } else if (report.inningEnded) {
      const breakCall = buildInningBreakCall(before, after, before.homeTeam, before.awayTeam, rng);
      voiceEnd = queue.say(breakCall, { notBefore: voiceEnd + INNING_BREAK_SEC, priority: PRIORITY.playByPlay });
      voiceEnd = queue.say(buildStationIdLine(rng), {
        notBefore: voiceEnd + 0.25,
        priority: PRIORITY.utility,
      });
      crowd.organStab(voiceEnd + 0.6, 329.63);
      crowd.setExcitement(currentExcitement(after), 2.0);
      nextGap = BETWEEN_PITCHES_SEC + 2.5;
    } else {
      crowd.setExcitement(currentExcitement(after), 2.0);
    }

    // Occasional Eric vendor line during a lull — queue so it yields to the booth.
    pitchesSinceVendor++;
    if (
      !report.gameEnded &&
      !report.inningEnded &&
      report.runsScored === 0 &&
      leverage < 1.2 &&
      pitchesSinceVendor >= 4 &&
      rng() < 0.22
    ) {
      pitchesSinceVendor = 0;
      const roll = rng();
      const kind: "dogs" | "beer" | "programs" =
        roll < 0.45 ? "dogs" : roll < 0.75 ? "beer" : "programs";
      queue.say(buildVendorLine(rng, kind), {
        notBefore: voiceEnd + 0.55,
        priority: PRIORITY.utility,
      });
    }

    return nextGap;
  }
}

/**
 * The count as it stood when the announcer describes the pitch.
 *
 * `GameState` zeroes the count the moment a plate appearance ends, but the call
 * still has to say "ball four" or "strike three" — so for a terminal pitch we
 * reconstruct the count that pitch produced rather than reading the fresh one.
 */
function countAfterFor(
  before: { balls: number; strikes: number },
  after: { balls: number; strikes: number },
  outcome: PlateOutcome,
): { balls: number; strikes: number } {
  switch (outcome.kind) {
    case "walk":
      return { balls: 4, strikes: before.strikes };
    case "strikeout":
      return { balls: before.balls, strikes: 3 };
    case "out":
    case "hit":
      return before;
    case "pitch":
      return after;
  }
}

function umpireCallFor(play: PlayResult, outcome: PlateOutcome): UmpireCall | null {
  if (outcome.kind === "strikeout") return "strike-three";
  switch (play) {
    case "called-strike":
      return "strike";
    case "ball":
      return "ball";
    case "foul-ball":
      return "foul";
    case "line-out":
    case "fly-out":
    case "ground-out":
    case "pop-up":
      return "out";
    // A swing and miss needs no announcement — everyone heard it.
    default:
      return null;
  }
}

function clampLevel(value: number): ExcitementLevel {
  return Math.min(5, Math.max(1, Math.round(value))) as ExcitementLevel;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function ordinal(value: number): string {
  const mod100 = value % 100;
  if (mod100 >= 11 && mod100 <= 13) return "th";
  switch (value % 10) {
    case 1: return "st";
    case 2: return "nd";
    case 3: return "rd";
    default: return "th";
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function waitForIdle(predicate: () => boolean): Promise<void> {
  return new Promise((resolve) => {
    const poll = setInterval(() => {
      if (!predicate()) return;
      clearInterval(poll);
      resolve();
    }, 30);
  });
}
