/**
 * Ratings — turn 1–99 player abilities into gameplay knobs.
 *
 * Difficulty remains the outer skill curve; ratings differentiate players
 * inside that curve so Arraez and Schwarber (or Skenes and a softer arm)
 * do not feel identical.
 */

import type { BatterRatings, PitcherRatings, Player } from "./Player.ts";
import { ratingFactor } from "./Player.ts";
import type { TimingWindows } from "../timing/SwingJudge.ts";
import type { PitchProfile, PitchType } from "../timing/Timeline.ts";
import { clamp, PITCH_PULSE_SEC } from "../timing/Timeline.ts";
import { PROFILES } from "./pitchProfiles.ts";

const DEFAULT_BATTER: BatterRatings = { contact: 70, eye: 70, power: 70, speed: 70 };
const DEFAULT_PITCHER: PitcherRatings = { velocity: 70, command: 70, stuff: 70 };

export function batterRatingsOf(player: Player | undefined): BatterRatings {
  return player?.batter ?? DEFAULT_BATTER;
}

export function pitcherRatingsOf(player: Player | undefined): PitcherRatings {
  return player?.pitcher ?? DEFAULT_PITCHER;
}

/** Slight window widen/narrow from contact — timing skill stays primary. */
export function windowsForBatter(base: TimingWindows, batter: BatterRatings): TimingWindows {
  const f = ratingFactor(batter.contact, 0.18);
  return {
    perfectWindowMs: Math.round(base.perfectWindowMs * f),
    contactWindowMs: Math.round(base.contactWindowMs * f),
  };
}

/**
 * Scale a base pitch profile by pitcher velocity.
 * Rating 70 ≈ stock velo; 94 (Skenes) pushes FB near 99–100.
 */
export function profileForPitcher(type: PitchType, pitcher: PitcherRatings): PitchProfile {
  const base = PROFILES[type];
  const veloFactor = ratingFactor(pitcher.velocity, 0.12);
  const velocityMph = Math.round(base.velocityMph * veloFactor);
  let flightSeconds = base.flightSeconds;
  if (type === "fastball") {
    flightSeconds = PITCH_PULSE_SEC * (base.velocityMph / Math.max(88, velocityMph));
  } else {
    flightSeconds = base.flightSeconds * (base.velocityMph / Math.max(70, velocityMph));
  }
  return {
    ...base,
    velocityMph,
    flightSeconds: clamp(flightSeconds, 0.38, 0.75),
  };
}

/** Command 40–95 → location scatter sigma (~0.50 → ~0.18). */
export function commandScatter(pitcher: PitcherRatings): number {
  return clamp(0.5 - ((pitcher.command - 40) / 55) * 0.32, 0.16, 0.52);
}

/** Stuff biases two-strike / arsenal picks toward miss pitches. */
export function stuffOffspeedBias(pitcher: PitcherRatings): number {
  return clamp((pitcher.stuff - 70) / 30, -0.35, 0.55);
}

export interface AiSkillMods {
  sigmaMs: number;
  zoneDiscipline: number;
  chase: number;
  /** Extra early bias on offspeed from pitcher stuff (ms magnitude). */
  offspeedEarlyMs: number;
}

export function modifyAiSkill(
  base: { sigmaMs: number; zoneDiscipline: number; chase: number },
  batter: BatterRatings,
  pitcher: PitcherRatings,
): AiSkillMods {
  const contactF = ratingFactor(batter.contact, 0.4);
  const eyeF = ratingFactor(batter.eye, 0.35);
  return {
    sigmaMs: base.sigmaMs / contactF,
    zoneDiscipline: clamp(base.zoneDiscipline * eyeF, 0.35, 0.98),
    chase: clamp(base.chase / eyeF, 0.12, 0.55),
    offspeedEarlyMs: 12 * stuffOffspeedBias(pitcher),
  };
}

/** Single send-chance multiplier from batter speed (1.0 at rating 70). */
export function hitAdvanceSpeedFactor(speed: number): number {
  return ratingFactor(speed, 0.25);
}
