import type { PitchLocation, PitchProfile, PitchType } from "../timing/Timeline.ts";
import type { BaseState, GameSnapshot, Half, PlayReport } from "./GameState.ts";
import type { PlayResult } from "./OutcomeResolver.ts";
import type { Team } from "./Teams.ts";

/**
 * LiveStats — everything an MLB Gameday panel needs beyond the bare GameState.
 *
 * Line score, batter/pitcher slash lines, and a pitch-by-pitch log for the
 * current plate appearance. Updated from the composition root after every pitch.
 */

export interface BatterLine {
  name: string;
  ab: number;
  r: number;
  h: number;
  rbi: number;
  bb: number;
  k: number;
  /** Ordinal in the lineup, 0–8. */
  order: number;
}

export interface PitcherLine {
  name: string;
  /** Outs recorded while pitching (for IP display). */
  outs: number;
  h: number;
  r: number;
  er: number;
  bb: number;
  k: number;
  pitches: number;
  strikes: number;
}

export interface PitchMarker {
  number: number;
  type: PitchType;
  label: string;
  velocityMph: number;
  location: PitchLocation;
  result: PlayResult;
  /** Ball / strike / in-play / foul for the pitch tray. */
  code: "B" | "S" | "X" | "F";
  inZone: boolean;
}

export interface AtBatPitchLog {
  batter: string;
  pitcher: string;
  pitches: PitchMarker[];
}

export interface LiveSnapshot {
  game: GameSnapshot;
  /** Runs per inning, index 0 = 1st. Grows into extras. */
  awayLine: number[];
  homeLine: number[];
  awayBatters: BatterLine[];
  homeBatters: BatterLine[];
  awayPitcher: PitcherLine;
  homePitcher: PitcherLine;
  currentAtBat: AtBatPitchLog;
  lastPitch: PitchMarker | null;
  /** All pitches this game, newest last — used for the zone plot trail. */
  pitchTrail: PitchMarker[];
}

export class LiveStats {
  private readonly home: Team;
  private readonly away: Team;

  private awayLine: number[] = [0];
  private homeLine: number[] = [0];
  private awayBatters: BatterLine[];
  private homeBatters: BatterLine[];
  private awayPitcher: PitcherLine;
  private homePitcher: PitcherLine;

  private currentAtBat: AtBatPitchLog;
  private lastPitch: PitchMarker | null = null;
  private pitchTrail: PitchMarker[] = [];
  private pitchNumberInAb = 0;

  constructor(home: Team, away: Team) {
    this.home = home;
    this.away = away;
    this.awayBatters = away.lineup.map((p, order) => emptyBatter(p.name, order));
    this.homeBatters = home.lineup.map((p, order) => emptyBatter(p.name, order));
    this.awayPitcher = emptyPitcher(away.pitcher.name);
    this.homePitcher = emptyPitcher(home.pitcher.name);
    this.currentAtBat = {
      batter: away.lineup[0]!.name,
      pitcher: home.pitcher.name,
      pitches: [],
    };
  }

  snapshot(game: GameSnapshot): LiveSnapshot {
    this.ensureInningColumns(game.inning);
    return {
      game,
      awayLine: [...this.awayLine],
      homeLine: [...this.homeLine],
      awayBatters: this.awayBatters.map((b) => ({ ...b })),
      homeBatters: this.homeBatters.map((b) => ({ ...b })),
      awayPitcher: { ...this.awayPitcher },
      homePitcher: { ...this.homePitcher },
      currentAtBat: {
        batter: this.currentAtBat.batter,
        pitcher: this.currentAtBat.pitcher,
        pitches: this.currentAtBat.pitches.map((p) => ({ ...p, location: { ...p.location } })),
      },
      lastPitch: this.lastPitch ? { ...this.lastPitch, location: { ...this.lastPitch.location } } : null,
      pitchTrail: this.pitchTrail.map((p) => ({ ...p, location: { ...p.location } })),
    };
  }

  /**
   * Record one pitch. `before` is the snapshot prior to `applyPlay`; `after` is
   * after. Plate-appearance bookkeeping keys off the report outcome.
   */
  recordPitch(args: {
    before: GameSnapshot;
    after: GameSnapshot;
    report: PlayReport;
    play: PlayResult;
    profile: PitchProfile;
    location: PitchLocation;
    inZone: boolean;
  }): PitchMarker {
    const { before, report, play, profile, location, inZone } = args;

    // New plate appearance: count was 0-0 before this pitch.
    if (before.balls === 0 && before.strikes === 0 && this.currentAtBat.pitches.length > 0) {
      this.beginAtBat(before);
    } else if (this.currentAtBat.pitches.length === 0) {
      this.beginAtBat(before);
    }

    this.pitchNumberInAb += 1;
    const marker: PitchMarker = {
      number: this.pitchNumberInAb,
      type: profile.type,
      label: profile.label,
      velocityMph: profile.velocityMph,
      location: { ...location },
      result: play,
      code: pitchCode(play),
      inZone,
    };

    this.currentAtBat.pitches.push(marker);
    this.lastPitch = marker;
    this.pitchTrail.push(marker);
    if (this.pitchTrail.length > 40) this.pitchTrail.shift();

    const pitcher = this.fieldingPitcher(before.half);
    pitcher.pitches += 1;
    if (marker.code === "S" || marker.code === "F" || marker.code === "X") pitcher.strikes += 1;

    this.applyScoring(before, report, play);
    this.applyPlateAppearance(before, report, play);

    return marker;
  }

  reset(): void {
    this.awayLine = [0];
    this.homeLine = [0];
    this.awayBatters = this.away.lineup.map((p, order) => emptyBatter(p.name, order));
    this.homeBatters = this.home.lineup.map((p, order) => emptyBatter(p.name, order));
    this.awayPitcher = emptyPitcher(this.away.pitcher.name);
    this.homePitcher = emptyPitcher(this.home.pitcher.name);
    this.currentAtBat = {
      batter: this.away.lineup[0]!.name,
      pitcher: this.home.pitcher.name,
      pitches: [],
    };
    this.lastPitch = null;
    this.pitchTrail = [];
    this.pitchNumberInAb = 0;
  }

  private beginAtBat(before: GameSnapshot): void {
    this.pitchNumberInAb = 0;
    this.currentAtBat = {
      batter: before.batter,
      pitcher: before.pitcher,
      pitches: [],
    };
  }

  private applyScoring(before: GameSnapshot, report: PlayReport, play: PlayResult): void {
    if (report.runsScored <= 0) return;
    this.ensureInningColumns(before.inning);
    const line = before.half === "top" ? this.awayLine : this.homeLine;
    line[before.inning - 1] = (line[before.inning - 1] ?? 0) + report.runsScored;

    const batters = before.half === "top" ? this.awayBatters : this.homeBatters;
    const batter = batters.find((b) => b.name === before.batter);
    if (batter) {
      batter.rbi += report.runsScored;
      // Only a home run scores the batter himself in this model (no triples).
      if (play === "home-run") batter.r += 1;
    }

    const pitcher = this.fieldingPitcher(before.half);
    pitcher.r += report.runsScored;
    pitcher.er += report.runsScored;
  }

  private applyPlateAppearance(before: GameSnapshot, report: PlayReport, play: PlayResult): void {
    const outcome = report.outcome.kind;
    if (outcome === "pitch") return;

    const batters = before.half === "top" ? this.awayBatters : this.homeBatters;
    const batter = batters.find((b) => b.name === before.batter);
    const pitcher = this.fieldingPitcher(before.half);
    if (!batter) return;

    switch (outcome) {
      case "walk":
        batter.bb += 1;
        pitcher.bb += 1;
        break;
      case "strikeout":
        batter.ab += 1;
        batter.k += 1;
        pitcher.k += 1;
        pitcher.outs += 1;
        break;
      case "out":
        // Sac flies are not charged as at-bats.
        if (report.note !== "sac-fly") batter.ab += 1;
        pitcher.outs += report.outsRecorded;
        break;
      case "hit":
        batter.ab += 1;
        batter.h += 1;
        pitcher.h += 1;
        break;
    }

    void play;
  }

  private fieldingPitcher(half: Half): PitcherLine {
    // Top: home pitches. Bottom: away pitches.
    return half === "top" ? this.homePitcher : this.awayPitcher;
  }

  private ensureInningColumns(inning: number): void {
    while (this.awayLine.length < inning) this.awayLine.push(0);
    while (this.homeLine.length < inning) this.homeLine.push(0);
  }
}

function emptyBatter(name: string, order: number): BatterLine {
  return { name, order, ab: 0, r: 0, h: 0, rbi: 0, bb: 0, k: 0 };
}

function emptyPitcher(name: string): PitcherLine {
  return { name, outs: 0, h: 0, r: 0, er: 0, bb: 0, k: 0, pitches: 0, strikes: 0 };
}

function pitchCode(play: PlayResult): PitchMarker["code"] {
  switch (play) {
    case "ball":
      return "B";
    case "foul-ball":
      return "F";
    case "called-strike":
    case "swinging-strike":
      return "S";
    default:
      return "X";
  }
}

export function formatIp(outs: number): string {
  const innings = Math.floor(outs / 3);
  const rem = outs % 3;
  return `${innings}.${rem}`;
}

export function formatAvg(h: number, ab: number): string {
  if (ab === 0) return ".---";
  return (h / ab).toFixed(3).replace(/^0/, "");
}

export function basesOccupied(bases: BaseState): number {
  return Number(bases.first) + Number(bases.second) + Number(bases.third);
}
