import type { PitchLocation, PitchType } from "../timing/Timeline.ts";

/**
 * Named location targets for the pitcher call pad — keyboard/SR friendly.
 */

export interface PitchTarget {
  readonly id: string;
  readonly label: string;
  readonly location: PitchLocation;
  /** Catcher's-view grid: row 0 = high, 2 = low; col 0 = inside, 2 = away. */
  readonly row: number;
  readonly col: number;
  /** True for the 3×3 strike zone; false for chase row. */
  readonly inZone: boolean;
}

/** 9 zone cells (catcher's view: inside is negative H for RHB) + chase spots. */
export const ZONE_TARGETS: readonly PitchTarget[] = [
  { id: "high-inside", label: "High and inside", location: { horizontal: -0.7, vertical: 0.75 }, row: 0, col: 0, inZone: true },
  { id: "high-middle", label: "High middle", location: { horizontal: 0, vertical: 0.75 }, row: 0, col: 1, inZone: true },
  { id: "high-away", label: "High and away", location: { horizontal: 0.7, vertical: 0.75 }, row: 0, col: 2, inZone: true },
  { id: "mid-inside", label: "Middle inside", location: { horizontal: -0.7, vertical: 0 }, row: 1, col: 0, inZone: true },
  { id: "middle", label: "Right down the middle", location: { horizontal: 0, vertical: 0 }, row: 1, col: 1, inZone: true },
  { id: "mid-away", label: "Middle away", location: { horizontal: 0.7, vertical: 0 }, row: 1, col: 2, inZone: true },
  { id: "low-inside", label: "Low and inside", location: { horizontal: -0.7, vertical: -0.75 }, row: 2, col: 0, inZone: true },
  { id: "low-middle", label: "Low middle", location: { horizontal: 0, vertical: -0.75 }, row: 2, col: 1, inZone: true },
  { id: "low-away", label: "Low and away", location: { horizontal: 0.85, vertical: -0.75 }, row: 2, col: 2, inZone: true },
];

export const CHASE_TARGETS: readonly PitchTarget[] = [
  { id: "chase-in", label: "Chase inside", location: { horizontal: -1.5, vertical: 0.2 }, row: 3, col: 0, inZone: false },
  { id: "in-dirt", label: "In the dirt", location: { horizontal: 0.15, vertical: -1.7 }, row: 3, col: 1, inZone: false },
  { id: "chase-away", label: "Chase low and away", location: { horizontal: 1.45, vertical: -1.2 }, row: 3, col: 2, inZone: false },
];

export const PITCH_TARGETS: readonly PitchTarget[] = [...ZONE_TARGETS, ...CHASE_TARGETS];

export const PITCH_TYPE_OPTIONS: readonly { id: PitchType; label: string; short: string }[] = [
  { id: "fastball", label: "Fastball", short: "FF" },
  { id: "slider", label: "Slider", short: "SL" },
  { id: "curveball", label: "Curveball", short: "CU" },
  { id: "changeup", label: "Changeup", short: "CH" },
];

const STORAGE_KEY = "botn.pitchCall";

export interface SavedPitchCall {
  type: PitchType;
  targetId: string;
}

export function targetById(id: string): PitchTarget | undefined {
  return PITCH_TARGETS.find((t) => t.id === id);
}

export function targetAt(row: number, col: number): PitchTarget | undefined {
  return PITCH_TARGETS.find((t) => t.row === row && t.col === col);
}

/**
 * Move selection on the 4×3 pad (3 zone rows + 1 chase). Clamps to the grid.
 * `dy` negative is up (toward high pitches).
 */
export function movePitchTarget(currentId: string, dx: number, dy: number): PitchTarget {
  const current = targetById(currentId) ?? ZONE_TARGETS[4]!;
  const row = clampInt(current.row + dy, 0, 3);
  const col = clampInt(current.col + dx, 0, 2);
  return targetAt(row, col) ?? current;
}

export function describePitchCall(typeLabel: string, targetLabel: string): string {
  return `${typeLabel}, ${targetLabel.toLowerCase()}.`;
}

export function loadSavedPitchCall(): SavedPitchCall {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as SavedPitchCall;
      if (
        PITCH_TYPE_OPTIONS.some((o) => o.id === parsed.type) &&
        targetById(parsed.targetId)
      ) {
        return parsed;
      }
    }
  } catch {
    // ignore
  }
  return { type: "fastball", targetId: "low-away" };
}

export function savePitchCall(call: SavedPitchCall): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(call));
  } catch {
    // ignore
  }
}

function clampInt(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}
